// --- localStorage Safe Fallback for Sandboxed Iframes ---
let safeLocalStorage;
try {
    const testKey = '__test_local_storage__';
    window.localStorage.setItem(testKey, '1');
    window.localStorage.removeItem(testKey);
    safeLocalStorage = window.localStorage;
} catch (e) {
    console.warn("localStorage is not accessible due to sandboxing. Using memory fallback.");
    const memoryStorage = {};
    safeLocalStorage = {
        getItem: function(key) {
            return key in memoryStorage ? memoryStorage[key] : null;
        },
        setItem: function(key, value) {
            memoryStorage[key] = String(value);
        },
        removeItem: function(key) {
            delete memoryStorage[key];
        },
        clear: function() {
            for (let key in memoryStorage) {
                delete memoryStorage[key];
            }
        },
        key: function(index) {
            const keys = Object.keys(memoryStorage);
            return keys[index] || null;
        },
        get length() {
            return Object.keys(memoryStorage).length;
        }
    };
}
const localStorage = safeLocalStorage;

// --- Geolocation Safe Fallback for Sandboxed Iframes ---
if (navigator.geolocation) {
    const originalGetCurrentPosition = navigator.geolocation.getCurrentPosition.bind(navigator.geolocation);
    navigator.geolocation.getCurrentPosition = function(successCallback, errorCallback, options) {
        try {
            originalGetCurrentPosition(
                successCallback,
                function(error) {
                    console.warn("Geolocation failed or blocked. Using fallback coordinates (Dar es Salaam).");
                    const mockPosition = {
                        coords: {
                            latitude: -6.7924,
                            longitude: 39.2083,
                            accuracy: 10,
                            altitude: null,
                            altitudeAccuracy: null,
                            heading: null,
                            speed: null
                        },
                        timestamp: Date.now()
                    };
                    successCallback(mockPosition);
                },
                options
            );
        } catch (e) {
            console.warn("getCurrentPosition threw error. Using Dar es Salaam fallback.");
            const mockPosition = {
                coords: {
                    latitude: -6.7924,
                    longitude: 39.2083,
                    accuracy: 10,
                    altitude: null,
                    altitudeAccuracy: null,
                    heading: null,
                    speed: null
                },
                timestamp: Date.now()
            };
            successCallback(mockPosition);
        }
    };
    
    const originalWatchPosition = navigator.geolocation.watchPosition.bind(navigator.geolocation);
    navigator.geolocation.watchPosition = function(successCallback, errorCallback, options) {
        try {
            return originalWatchPosition(
                successCallback,
                function(error) {
                    console.warn("watchPosition failed or blocked. Using fallback coordinates (Dar es Salaam).");
                    const mockPosition = {
                        coords: {
                            latitude: -6.7924,
                            longitude: 39.2083,
                            accuracy: 10,
                            altitude: null,
                            altitudeAccuracy: null,
                            heading: null,
                            speed: null
                        },
                        timestamp: Date.now()
                    };
                    successCallback(mockPosition);
                },
                options
            );
        } catch (e) {
            console.warn("watchPosition threw error. Using simulated timer fallback.");
            const intervalId = setInterval(() => {
                const mockPosition = {
                    coords: {
                        latitude: -6.7924,
                        longitude: 39.2083,
                        accuracy: 10,
                        altitude: null,
                        altitudeAccuracy: null,
                        heading: null,
                        speed: null
                    },
                    timestamp: Date.now()
                };
                successCallback(mockPosition);
            }, 3000);
            return intervalId;
        }
    };
}

