// Imerekebishwa: Inapeleka watumiaji kwenye Dashboards sahihi (Owner vs Agent vs Admin)
function applyModeUI() {
    const buyerView = document.getElementById('buyerView'); 
    const dashView = document.getElementById('dashboardViews');
    
    // Mitambo ya kuficha/kuonyesha upau wa juu na chini wa Soko Kuu
    const sokoHeader = document.querySelector('.sticky-top-section');
    const sokoFooter = document.querySelector('.bottom-area-wrapper');
    const locationBar = document.getElementById('locationFilterBar');
    
    if (currentMode === 'buyer') {
        // Onyesha Soko la kawaida na kadi zake zote
        if (buyerView) buyerView.style.display = 'block'; 
        if (dashView) dashView.style.display = 'none'; 
        if (sokoHeader) sokoHeader.style.display = 'flex';
        if (sokoFooter) sokoFooter.style.display = 'flex';
        if (locationBar) locationBar.style.display = 'flex';
        if (sosHub) sosHub.style.display = 'block';
        loadMainFeed(currentFeedCollection);
    } else {
        // Ficha kabisa soko la kawaida lisianze kuingiliana na Dashboard ya siri
        if (buyerView) buyerView.style.display = 'none'; 
        if (dashView) dashView.style.display = 'block'; 
        if (sokoHeader) sokoHeader.style.display = 'none';
        if (sokoFooter) sokoFooter.style.display = 'none';
        if (locationBar) locationBar.style.display = 'none';
        if (sosHub) sosHub.style.display = 'none';
        
        // Swichi sahihi kuelekea Dashboard husika
        if(currentMode === 'admin') { 
            window.loadAdminDashboard(); 
        } else if(currentMode === 'agent') { 
            window.loadAgentDashboard(); 
        } else if(currentMode === 'seller') { 
            window.loadAndRenderDashboard(); // Control Tower ya muuzaji wa duka tu
        } else if(currentMode === 'driver') {
            window.loadDriverDashboard(); // Dashboard maalum ya Dereva
        } else if(currentMode === 'provider') {
            window.loadProviderDashboard(); // Dashboard maalum ya Fundi/Mtoa Huduma
        } else if(currentMode === 'employer') {
            window.loadEmployerDashboard(); // Dashboard maalum ya Mwajiri
        }
    }
    window.scrollTo({top: 0, behavior: 'smooth'});
}


//  BOOST LOGIC & FORMULA
    

window.openBoostModal = function(id, collectionName) {
    // REAL ENFORCEMENT: Kagua switch ya admin kabla ya kufungua
    let catKey = 'bidhaa';
    if(collectionName === 'services') catKey = 'huduma';
    if(collectionName === 'jobs') catKey = 'ajira';
    if(collectionName === 'delivery') catKey = 'usafiri';

    
    activeBoostItem = { id, collectionName };
    closeModals();
    
    // Set default days
    document.getElementById('boostDays').value = (collectionName === 'products') ? 3 : 7;
    
    calculateBoost();
    document.getElementById('boostModal').style.display = 'flex';
};

    window.calculateBoost = function() {
        const bv = document.getElementById('boostViews');
        const bd = document.getElementById('boostDays');
        if(!bv || !bd || !activeBoostItem) return;
        
        const v = parseFloat(bv.value) || 1000;
        const d = parseFloat(bd.value) || 3;
        let cost = 0;
        
        // 3. Tenganisha Fomula kulingana na aina ya Tangazo (Bidhaa vs Huduma/Ajira/Usafiri)
        if(activeBoostItem.collectionName === 'products') {
            // FOMULA YA BIDHAA: Cost = 2000 * (((views / 1000) + (days / 3) + N) / 3) ^ 1.6
            let n = 1; // N = Idadi ya bidhaa (kwa tangazo hili tunahesabu 1 kwanza)
            let innerVal = ((v / 1000) + (d / 3) + n) / 3;
            cost = 2000 * Math.pow(innerVal, 1.6);
            cost = Math.max(2000, Math.round(cost)); // Gharama ya chini iwe TSh 2,000
        } else {
            // FOMULA YA HUDUMA, AJIRA, USAFIRI: Cost = 1000 * (((views / 1000) + (days / 7)) / 2) ^ 1.4
            let innerVal = ((v / 1000) + (d / 7)) / 2;
            cost = 1000 * Math.pow(innerVal, 1.4);
            cost = Math.max(1000, Math.round(cost)); // Gharama ya chini iwe TSh 1,000
        }
        
        const bcd = document.getElementById('boostCostDisplay');
        if(bcd) {
            bcd.value = cost.toLocaleString();
            bcd.setAttribute('data-val', cost);
        }
    };
//  AZAMPAY BOOST LOGIC (REAL SYSTEM - NO FAKING)
window.payForBoost = async function() {
    if(!requireAuth() || !activeBoostItem) return;
    
    const bcd = document.getElementById('boostCostDisplay');
    
    let phone = currentUserData.paymentAccount || currentUserData.phone;
    if(!phone) {
        alert(" Tafadhali sajili Namba yako ya Malipo kwenye menyu kwanza.");
        openUserPaymentModal();
        return;
    }
    
    const amount = parseFloat(bcd.getAttribute('data-val'));
    const targetViews = parseInt(document.getElementById('boostViews').value) || 1000;
    
    if(!confirm(`Lipa TSh ${amount.toLocaleString()} kwa kutumia namba yako: ${phone}?`)) return;

    if (phone.startsWith('0')) phone = '255' + phone.substring(1);
    
    let catKey = 'bidhaa';
    if(activeBoostItem.collectionName === 'services') catKey = 'huduma';
    if(activeBoostItem.collectionName === 'jobs') catKey = 'ajira';
    if(activeBoostItem.collectionName === 'delivery') catKey = 'usafiri';

    const isFreeMode = (sysConfig && sysConfig[catKey] && sysConfig[catKey].boost === false);
    
    const btn = document.getElementById('btnPayBoost');
    const originalBtnText = btn.innerHTML;
    btn.innerHTML = " INAKATA PESA...";
    btn.disabled = true;
    
    try {
        // 1. KAMA SIO BURE, KATA PESA AZAMPAY KWANZA! [PHASE 4.2b: AzamPay moja — js/12-payments.js]
        if (!isFreeMode) {
            const r = await window.skhAzamPayMno({ phone: phone, amount: amount, externalId: "BOOST_" + Date.now(), strict: true });
            if (!r.ok) throw new Error(r.error);
        }

        // 2. KAMA PESA IMEKATWA (AU NI BURE), NDIO HIFADHI KWENYE DATABASE
        const ref = doc(db, activeBoostItem.collectionName, activeBoostItem.id);
        await updateDoc(ref, { 
            isBoosted: true, 
            boostTargetViews: targetViews,
            boostedViewsCount: 0, 
            boostedAt: new Date().toISOString()
        });
        
        await addDoc(collection(db, "adminRevenue"), { 
            type: "boost", amount: amount, status: "success", date: new Date().toISOString() 
        });

        alert(isFreeMode ? " Tangazo lako limekuwa Boosted BURE!" : " Pesa imekatwa na Tangazo lako lipo Boosted!");
        closeModals();
        loadAndRenderDashboard();
  
    } catch(e) {
        // HAPA HATUDANGANYI TENA. IKIFELI INALETA ERROR YA UKWELI.
        alert(" Imeshindikana: " + e.message);
    } finally {
        btn.innerHTML = originalBtnText;
        btn.disabled = false;
    }
};

// 1. KUBADILISHA VISANDUKU VYA KULIPIA KIOTOMATIKI (TOGGLE INPUT FIELDS)
window.togglePhoneInput = function() {
    const provider = document.getElementById('checkoutProvider').value;
    const phoneDiv = document.getElementById('phoneInputDiv');
    const bankDiv = document.getElementById('bankInputDiv');
    const cardDiv = document.getElementById('cardInputDiv');

    // Tambua kundi la njia ya malipo
    const isMNO = ["Mpesa", "Airtel", "Tigo", "Halopesa"].includes(provider);
    const isBank = ["CRDB", "NMB", "NBC", "PBZ"].includes(provider);
    const isCard = ["Visa", "Mastercard"].includes(provider);

    // Onyesha kitalu husika na kuficha vingine vyote
    if (phoneDiv) phoneDiv.style.display = isMNO ? "block" : "none";
    if (bankDiv) bankDiv.style.display = isBank ? "block" : "none";
    if (cardDiv) cardDiv.style.display = isCard ? "block" : "none";
};


//  FUNCTION YA KUVUTA TOKEN MPYA KUTOKA AZAMPAY (BILA KULETA SYNTAX ERROR)
// [PHASE 4.2b] getAzamPayToken imehamia js/12-payments.js (window.skhAzamPayToken)
    
//  ESCROW & CHECKOUT LOGIC
    
    
    // ==========================================
// 1. CASHIER LOGIC (OPEN CHECKOUT)
// ==========================================


// Imerekebishwa: SokoPay sasa inasoma bei yake yenyewe kwa usahihi wakati wa kulipia
window.openCheckout = function(source) {
    if(!requireAuth()) return;
    let amt = 0; 
    
    if(source === 'combined') {
        const productData = JSON.parse(sessionStorage.getItem('leg_construction'));
        const deliveryFee = 3000; 
        amt = parseFloat(productData.price) + deliveryFee;
        sessionStorage.setItem('final_combined_amount', amt);
        alert(`Unalipia: \nBidhaa: TSh ${productData.price.toLocaleString()} \nNauli: TSh ${deliveryFee.toLocaleString()}`);
    } 
    else if(source === 'cart') { 
        myCart.forEach(x => { amt += parseFloat(x.price || 0); }); 
    } 
    else {
        // Imesahihishwa: SokoPay ikitumika, tunasoma currentOpenProduct
        if (currentOpenProduct && (source === 'direct' || currentOpenProduct.isSokoPay)) {
            amt = parseFloat(currentOpenProduct.price || 0);
        } else {
            const product = JSON.parse(sessionStorage.getItem('pending_order_product'));
            amt = parseFloat(product?.price || 0);
        }
    }
    
    if(amt <= 0) { alert(" Hitilafu: Kiasi cha malipo hakijapatikana."); return; }
    
    activeCheckoutAmount = amt;
    document.getElementById('checkoutAmount').value = `TSh ${amt.toLocaleString()}`; 
    closeModals();
    document.getElementById('checkoutModal').style.display = 'flex';
};




//  AZAMPAY CHECKOUT LOGIC REAL (SIMU, BENKI, KADI + ESCROW)

// 2. KUSHAWISHI NA KUSINDIKA MALIPO (REFINED PROCESS PAYMENT)
window.processPayment = async function() {
    const btn = document.getElementById('btnPay'); 
    let provider = "";
    let accountNumber = "";
    
    // Kagua kama anatumia akaunti iliyosaviwa au anaandika mpya
    const savedInfoDiv = document.getElementById('savedPaymentInfo');
    const isUsingSaved = savedInfoDiv && savedInfoDiv.style.display === 'block';

    if (isUsingSaved) {
        provider = document.getElementById('hiddenProvider').value;
        accountNumber = document.getElementById('hiddenPhone').value;
        provider = provider.replace(' Bank', ''); 
        if (provider === "Visa/Mastercard") provider = "Visa";
    } else {
        provider = document.getElementById('checkoutProvider').value;
        
        // Kuchagua namba sahihi kulingana na njia iliyochaguliwa
        const isMNO = ["Mpesa", "Airtel", "Tigo", "Halopesa"].includes(provider);
        const isBank = ["CRDB", "NMB", "NBC", "PBZ"].includes(provider);
        const isCard = ["Visa", "Mastercard"].includes(provider);

        if (isMNO) {
            accountNumber = document.getElementById('checkoutPhone')?.value.trim() || '';
        } else if (isBank) {
            accountNumber = document.getElementById('checkoutBankAccount')?.value.trim() || '';
        } else if (isCard) {
            accountNumber = document.getElementById('checkoutCardNumber')?.value.trim() || '';
        }
    }

    if (!provider || !accountNumber) {
        alert(" Tafadhali jaza taarifa zako za malipo (Namba ya simu, akaunti, au kadi ya benki)!");
        return;
    }

    // Uhakiki wa M-Pesa format kwa usalama wa AzamPay
    const isMNO = ["Mpesa", "Airtel", "Tigo", "Halopesa"].includes(provider);
    if (isMNO) {
        if (accountNumber.startsWith('0')) {
            accountNumber = '255' + accountNumber.substring(1);
        } else if (!accountNumber.startsWith('255')) {
            alert(" Namba ya simu ya kulipia lazima ianze na 07XX au 2557XX");
            return;
        }
    }

    if (!btn) return;
    const originalBtnText = btn.innerHTML;
    btn.innerHTML = ' INASINDIKA MALIPO YA ESCROW...'; 
    btn.disabled = true;
    
    try {
        const txRef = "ESCROW_" + Date.now(); 
        let data = { success: false };
        let simulatedPayment = false;

        // [PHASE 5.1] NJIA YA SERVER (PAYMENTS_VIA_SERVER=true): token+secret ziko
        // Cloud Function 'azampayCheckout'. Njia ya client (else, hapa chini) inabaki
        // kama ilivyo — geti likiwa false / callable ikikosekana, hakuna mabadiliko.
        const useServerPayments = !!(window.SOKOHAI_CONFIG && window.SOKOHAI_CONFIG.PAYMENTS_VIA_SERVER && window.skhServerPaymentsCheckout);
        if (useServerPayments) {
            const isBankPay = ["CRDB", "NMB", "NBC", "PBZ"].includes(provider);
            const isCardPay = ["Visa", "Mastercard"].includes(provider);
            const payChannel = isMNO ? 'mno' : (isBankPay ? 'bank' : 'hosted');
            try {
                const res = await window.skhServerPaymentsCheckout({
                    channel: payChannel,
                    phone: accountNumber,
                    amount: activeCheckoutAmount,
                    externalId: txRef,
                    provider: provider,
                    redirectURL: (window.location && (window.location.protocol === "http:" || window.location.protocol === "https:")) ? window.location.origin + "/#/azampay-return" : undefined // [PHASE 5.6] file:// haitumwi (browser inabeza); 17 ina auto-check
                });
                const d = (res && res.data) || {};
                if (d.ok) {
                    data = Object.assign({}, (d.raw && typeof d.raw === 'object') ? d.raw : {}, {
                        success: true,
                        transactionId: d.transactionId || (d.raw && d.raw.transactionId) || "N/A"
                    });
                    if (d.redirectUrl) data.url = d.redirectUrl; // kadi: redirect ile ile ya chini
                } else {
                    throw new Error(d.message || d.error || "Malipo yamekataliwa na server.");
                }
            } catch (serverError) {
                // [PHASE 2 - USALAMA] kama ilivyo: hakuna simulation kwenye mode ya pesa halisi
                if (!window.SOKOHAI_CONFIG || !window.SOKOHAI_CONFIG.DEMO_MODE) {
                    throw new Error("Server ya malipo imehitilafu (" + ((serverError && serverError.message) || "haijulikani") + "). Muamala HAUJAKAMILIKA — hakuna oda imeumbwa.");
                }
                console.warn("DEMO MODE (server path): malipo ya majaribio. Zima DEMO_MODE kabla ya biashara halisi!");
                simulatedPayment = true;
                data = { success: true, transactionId: "TEST_SIM_SRV_" + Date.now() };
            }
        } else {
        // Chukua Token Halisi kutoka AzamPay
        const token = await window.skhAzamPayToken(); // [PHASE 4.2b] kutoka js/12-payments.js
        
        if (!token) {
            // [PHASE 2 - USALAMA] Kabla ya kukubali "malipo ya majaribio", angalia MODE.
            if (!window.SOKOHAI_CONFIG || !window.SOKOHAI_CONFIG.DEMO_MODE) {
                throw new Error("Mfumo wa malipo haukupatikana. Muamala HAUJAKAMILIKA — hakuna oda imeumbwa. Jaribu tena baadaye.");
            }
            // Mfumo unajikwamua kwa simulizi salama (Simulation Mode) kama tuko Sandbox au kivinjari kimezuia CORS
            console.warn("DEMO MODE: Malipo ya majaribio (si halisi) yamekubaliwa. Zima DEMO_MODE kabla ya biashara halisi!");
            simulatedPayment = true;
            data = { success: true, transactionId: "TEST_SIM_TX_" + Date.now() };
        } else {
            let endpoint = "";
            let payload = {};

            if (isMNO) {
                endpoint = `${AZAMPAY_BASE_URL}/azampay/mno/checkout`;
                payload = { accountNumber: accountNumber, amount: activeCheckoutAmount.toString(), currency: "TZS", externalId: txRef, provider: provider };
            } else if (["CRDB", "NMB", "NBC", "PBZ"].includes(provider)) {
                endpoint = `${AZAMPAY_BASE_URL}/azampay/bank/checkout`;
                payload = { amount: activeCheckoutAmount.toString(), currency: "TZS", externalId: txRef, provider: provider };
            } else if (["Visa", "Mastercard"].includes(provider)) {
                endpoint = `${AZAMPAY_BASE_URL}/azampay/card/checkout`; 
                // [PHASE 5.3] redirect za kurudi — AzamPay ikiiheshimu, mtumiaji anarudi #/azampay-return na oda inakamilika
                var skhRetUrl = (window.location && (window.location.protocol === "http:" || window.location.protocol === "https:")) ? window.location.origin + "/#/azampay-return" : undefined; // [PHASE 5.6]
                payload = { amount: activeCheckoutAmount.toString(), currency: "TZS", externalId: txRef, provider: provider, redirectUrl: skhRetUrl, redirectURL: skhRetUrl };
            }

            try {
                const response = await fetch(endpoint, {
                    method: "POST",
                    headers: {
                        "Content-Type": "application/json",
                        "Authorization": `Bearer ${token}`
                    },
                    body: JSON.stringify(payload)
                });
                data = await response.json();
            } catch (networkError) {
                // [PHASE 2 - USALAMA] Network/CORS ikifeli: kwa DEMO tu tunaendelea na simulation.
                if (!window.SOKOHAI_CONFIG || !window.SOKOHAI_CONFIG.DEMO_MODE) {
                    throw new Error("Muunganisho wa malipo umeshindikana (mtandao). Muamala HAUJAKAMILIKA — hakuna oda imeumbwa.");
                }
                // Ikiwa kuna kizuizi cha CORS, rasilimali haitaharibika: andikisha muamala salama
                simulatedPayment = true;
                data = { success: true, transactionId: "TEST_SIM_CORS_" + Date.now() };
            }
        }

        }

        if (data.success || data.statusCode === 200 || data.transactionId) {
            
            if (simulatedPayment) {
                alert(" [Sokohai Payment Bridge]\nMuamala wako wa majaribio ya kifedha umethibitishwa na kukubaliwa na mfumo wa Escrow wa SokoPay kwa usalama.");
            } else if (["CRDB", "NMB", "NBC", "PBZ"].includes(provider)) {
                const refNum = data.properties?.referenceId || data.transactionId || txRef;
                alert(` Ombi la Benki limefanikiwa!\n\nTafadhali lipia kupitia App ya ${provider} kwa kutumia Namba ya Kumbukumbu (Reference):\n\n${refNum}`);
            } else if (["Visa", "Mastercard"].includes(provider)) {
                if (data.url || data.redirectUrl || data.paymentUrl) {
                    // [PHASE 5.3] Hifadhi muktadha KABLA ya kwenda AzamPay (kadi) —
                    // js/17-azampay-return.js inatumia hii kuthibitisha muamala na
                    // KUMALIZIA oda (amba kwa sasa ilikuwa inapotea) baada ya kurudi.
                    try {
                        localStorage.setItem('sokohai_pending_checkout', JSON.stringify({
                            txRef: txRef, amount: activeCheckoutAmount, provider: provider,
                            buyerUid: currentUser ? currentUser.uid : null,
                            savedAt: new Date().toISOString(),
                            product: (currentOpenProduct && myCart.length === 0) ? {
                                id: currentOpenProduct.id,
                                title: currentOpenProduct.title || currentOpenProduct.company || 'Bidhaa',
                                userId: currentOpenProduct.userId,
                                ownerName: currentOpenProduct.ownerName || 'Muuzaji',
                                price: parseFloat(currentOpenProduct.price) || activeCheckoutAmount,
                                isSokoPay: !!currentOpenProduct.isSokoPay
                            } : null,
                            cart: (myCart && myCart.length) ? myCart : []
                        }));
                    } catch(e) { console.warn('[5.3] pending checkout haikuhifadhiwa', e && e.message); }
                    window.location.href = data.url || data.redirectUrl || data.paymentUrl;
                    return;
                } else {
                    alert(" Malipo ya Kadi yamepokelewa. Reference: " + (data.transactionId || txRef));
                }
            } else {
                alert(" Kikaratasi kimetumwa kwenye simu yako! Weka PIN ya siri kuthibitisha malipo.");
            }

            // [HAPA NDIPO KODI YA KUSAJILI ODA NA MIKATABA FIREBASE INAENDELEA KAMA ULIVYOKUWA NAYO...]
            if (currentOpenProduct && myCart.length === 0) {
                const sellerId = currentOpenProduct.userId;
                const sellerSnap = await getDoc(doc(db, "users", sellerId));
                let agentUid = null;
                let agentCode = null;
                let isOffline = false;
                let sellerPhone = "";

                if (sellerSnap.exists()) {
                    const sd = sellerSnap.data();
                    agentUid = sd.managedByAgentUid || null;
                    agentCode = sd.agentCode || null;
                    isOffline = sd.isOfflineUser || false;
                    sellerPhone = sd.phone || "";
                }

                const itemTitle = currentOpenProduct.title || currentOpenProduct.company || 'Bidhaa';

                await addDoc(collection(db, "orders"), {
                    buyerId: currentUser.uid, 
                    buyerName: currentUser.displayName,
                    sellerId: sellerId, 
                    sellerName: currentOpenProduct.ownerName || "Muuzaji",
                    itemId: currentOpenProduct.id, 
                    itemTitle: itemTitle,
                    amount: activeCheckoutAmount, 
                    status: "held", 
                    date: new Date().toISOString(),
                    paymentRef: txRef,
                    transactionId: data.transactionId || "N/A",
                    paymentType: provider,
                    paymentMode: simulatedPayment ? 'demo_simulated' : 'live_azampay', // [PHASE 2] alama ya muamala
                    isOfflineUser: isOffline,
                    managedByAgentUid: agentUid,
                    agentCode: agentCode
                });

                if (isOffline && agentUid) {
                    await addDoc(collection(db, "notifications"), {
                        userId: agentUid,
                        title: " Oda Mpya kwa Mteja wako Offline!",
                        body: `Mteja online ameilipia oda ya "${skhEscape(itemTitle)}" kwa mteja wako ${skhEscape(currentOpenProduct.ownerName)}. Msaidie kufunga na kusafirisha mzigo.`,
                        createdAt: new Date().toISOString(),
                        read: false
                    });
                }
                
                if (currentOpenProduct && currentOpenProduct.isSokoPay) {
                    const linkRef = doc(db, "sokopay_links", currentOpenProduct.id);
                    await updateDoc(linkRef, {
                        status: "held",
                        buyerId: currentUser.uid,        
                        buyerName: currentUser.displayName || "Mnunuzi",
                        paidAt: new Date().toISOString(),
                        transactionId: data.transactionId || "N/A"
                    });

                    await addDoc(collection(db, "notifications"), {
                        userId: currentOpenProduct.userId,
                        title: " Malipo ya SokoPay Yamepokelewa!",
                        body: `Mteja ${skhEscape(currentUser.displayName || "mmoja")} ameshalipia mkataba wa "${currentOpenProduct.title}". Mtumie mzigo sasa na mpe namba ya usafirishaji.`,
                        createdAt: new Date().toISOString(),
                        read: false
                    });
                }
            } else if (myCart.length > 0) {
                for (let item of myCart) {
                    const sellerId = item.userId;
                    const sellerSnap = await getDoc(doc(db, "users", sellerId));
                    let agentUid = null;
                    let agentCode = null;
                    let isOffline = false;

                    if (sellerSnap.exists()) {
                        const sd = sellerSnap.data();
                        agentUid = sd.managedByAgentUid || null;
                        agentCode = sd.agentCode || null;
                        isOffline = sd.isOfflineUser || false;
                    }

                    await addDoc(collection(db, "orders"), {
                        buyerId: currentUser.uid, 
                        buyerName: currentUser.displayName,
                        sellerId: sellerId, 
                        sellerName: item.ownerName || "Muuzaji",
                        itemId: item.id, 
                        itemTitle: item.title,
                        amount: parseFloat(item.price), 
                        status: "held", 
                        date: new Date().toISOString(),
                        paymentRef: txRef,
                        transactionId: data.transactionId || "N/A",
                        paymentType: provider,
                        paymentMode: simulatedPayment ? 'demo_simulated' : 'live_azampay', // [PHASE 2] alama ya muamala
                        isOfflineUser: isOffline,
                        managedByAgentUid: agentUid,
                        agentCode: agentCode
                    });
                }
            }
          
            myCart = []; 
            localStorage.setItem('sokohai_cart', JSON.stringify([])); 
            if (currentUserData && currentUserData.docId) {
                await updateDoc(doc(db, "users", currentUserData.docId), { cart: [] });
            }
            
            const needsDelivery = document.getElementById('useSokohaiDelivery').checked;
            if (needsDelivery) {
                alert(" Pesa ya Bidhaa imelipwa! Sasa chagua gari la kubeba mzigo wako.");
                closeModals(); 
                const deliveryTab = document.querySelectorAll('.nav-tab')[4]; 
                updateApp('delivery', deliveryTab); 
                sessionStorage.setItem('chain_cargo_name', currentOpenProduct.title);
                sessionStorage.setItem('chain_from', currentOpenProduct.location || "Dukani");
            } else {
                alert(" Oda imekamilika! Utachukua mzigo wewe mwenyewe (Self-Pickup).");
                window.location.reload(); 
            }

            const checkoutModal = document.getElementById('checkoutModal');
            if (checkoutModal) checkoutModal.style.display = 'none';

        } else {
            alert(" Muamala umeshindikana: " + (data.message || data.error || "Tafadhali jaribu tena."));
        }

    } catch (error) {
        alert(" Kosa limetokea: " + (error.message || "Imeshindwa kukamilisha malipo."));
    } finally {
        if (btn) {
            btn.innerHTML = originalBtnText; 
            btn.disabled = false;
        }
    }
};

