window.loadBuyerOrdersWithTracking = async function() {
    const list = document.getElementById('buyerOrdersModalList');
    if(!list) return;

    list.innerHTML = '<p style="text-align:center; color:#64748b; padding:20px;"> Inapakia oda na safari zako...</p>';

    try {
        // 1. Vuta Oda za Bidhaa na safari za usafiri kwa pamoja
        const qOrders = query(collection(db, "orders"), where("buyerId", "==", currentUser.uid));
// Oda mpya itakuwa juu kabisa
const qRides = query(
    collection(db, "ride_requests"), 
    where("customerId", "==", currentUser.uid),
    orderBy("createdAt", "desc") // <--- Hii inapanga mpya juu
);
        const [snapOrders, snapRides] = await Promise.all([getDocs(qOrders), getDocs(qRides)]);

        let html = '';

        // 2. CHORA ODA ZA BIDHAA
        if(!snapOrders.empty) {
            snapOrders.forEach(docSnap => {
                const od = docSnap.data();
                const status = od.status;
                let progressWidth = "5%"; 
                let step1Class = "done", step2Class = "", step3Class = "", step4Class = "";

                if(status === 'shipped') { progressWidth = "50%"; step2Class = "active"; }
                else if(status === 'completed') { progressWidth = "100%"; step1Class = "done"; step2Class = "done"; step3Class = "done"; step4Class = "done"; }

                const canArchive = (status === 'completed' || status === 'refunded_by_admin');
                html += `
                    <div style="background:#f8fafc; border:1px solid #e2e8f0; padding:15px; border-radius:16px; margin-bottom:15px;">
                        <div style="display:flex; justify-content:space-between; margin-bottom:10px;">
                            <b style="color:var(--primary-dark);"> Bidhaa: ${skhEscape(od.itemTitle)}</b>
                            <div>
                                <span style="font-size:11px; font-weight:bold; color:var(--terracotta); margin-right:8px;">TSh ${od.amount.toLocaleString()}</span>
                                ${canArchive ? `<button onclick="window.deleteOrderLog('${docSnap.id}')" style="background:none; border:none; color:#ef4444; font-weight:bold; cursor:pointer;" title="Futa Rekodi"></button>` : ''}
                            </div>
                        </div>
                        <div class="tracker-wrap">
                            <div class="tracker-line"></div>
                            <div class="tracker-fill" style="width: ${progressWidth};"></div>
                            <div class="tracker-steps">
                                <div class="t-step ${step1Class}"><div class="t-dot"></div><span class="t-label">Seller</span></div>
                                <div class="t-step ${step2Class}"><div class="t-dot"></div><span class="t-label">Safarini</span></div>
                                <div class="t-step"><div class="t-dot"></div><span class="t-label">Kituoni</span></div>
                                <div class="t-step ${step4Class}"><div class="t-dot"></div><span class="t-label">Mteja</span></div>
                            </div>
                        </div>
                        <div style="margin-top:15px;">
                            ${status === 'shipped' ? 
                                `<button onclick="openEscrowModal('${docSnap.id}', '${od.sellerId}', ${od.amount})" style="width:100%; padding:12px; background:var(--green); color:white; border:none; border-radius:10px; font-weight:bold; cursor:pointer;"> NIMEPOKEA MZIGO</button>` : 
                                `<p style="font-size:12px; color:#64748b; text-align:center; background:#eee; padding:5px; border-radius:5px;">Hali: <b>${status.toUpperCase()}</b></p>`
                            }
                        </div>
                    </div>
                `;
            });
        }

        // 3. CHORA MAOMBI YA USAFIRI (RIDE REQUESTS)
     if(!snapRides.empty) {
            snapRides.forEach(rDoc => {
                const rd = rDoc.data();
                let actionArea = "";
// Ndani ya snapRides.forEach...
const isFinished = (rd.status === 'completed' || rd.status === 'cancelled');

html += `
    <div style="...">
        ...
        ${isFinished ? `<button onclick="deleteRideOrder('${rDoc.id}')" style="color:red; background:none; border:none; float:right; font-size:11px;"> Futa Kumbukumbu</button>` : ''}
    </div>
`;
if(rd.status === 'in_transit') {
    html += `
    <button onclick="openLiveMap('${rDoc.id}')" style="width:100%; padding:12px; background:var(--primary-blue); color:white; border:none; border-radius:10px; font-weight:bold; margin-top:10px; display:flex; align-items:center; justify-content:center; gap:8px;">
         ONA GARI LIPO WAPI (LIVE)
    </button>`;
}
                // Logic ya Chain: Kama mzigo umefika Hub (Mkoani), mteja aongeze safari nyingine
                if(rd.status === 'arrived_at_hub') {
                    actionArea = `<button onclick="chainNextLeg('${rDoc.id}', '${rd.toLocation}', '${rd.cargoName}')" style="width:100%; padding:12px; background:var(--gold); border:none; border-radius:10px; font-weight:900; margin-top:10px;"> UNGA USAFIRI WA WILAYANI</button>`;
                } 
                else if(rd.status === 'in_transit') {
                    actionArea = `<p style="color:var(--green); text-align:center; font-weight:bold;"> Mzigo upo njiani...</p>`;
                }


    html += `
                    <div style="background:#fffbeb; border:1px solid var(--gold); padding:15px; border-radius:16px; margin-bottom:15px;">
                        <b style="color:var(--primary-dark);"> Safari: ${rd.cargoName}</b>
                        <p style="font-size:12px; color:#475569;"> ${rd.fromLocation} ➡ ${rd.toLocation}</p>
                        
                        <div style="background:white; padding:12px; border-radius:12px; margin-top:10px; border: 1px dashed #f97316;">
                            <p style="font-size:11px; color:#9a3412; margin:0;"><b> CODE YAKO YA UTHIBITISHO:</b></p>
                            <h1 style="text-align:center; color:orange; margin:5px 0;">${rd.transferCode}</h1>
                            <small style="font-size:9px; display:block; text-align:center;">Mpe namba hii mtu anayepaswa kupokea mzigo huu (Dereva au Mteja wa mwisho).</small>
                        </div>
                        ${actionArea}
                    </div>`;
            });
        }   
        
        if(snapOrders.empty && snapRides.empty) {
            list.innerHTML = '<p style="text-align:center; padding:20px;">Huna oda wala safari yoyote kwa sasa.</p>';
        } else {
            list.innerHTML = html;
        }

    } catch(e) {
        list.innerHTML = '<p style="color:red; text-align:center;">Hitilafu: ' + e.message + '</p>';
    }
};


    

