//  AUTH STATE & USER REAL-TIME SYNC (WITH DASHBOARD AUTO TRIGGER)
// ==========================================


// ==========================================
//  AUTH STATE & USER REAL-TIME SYNC (WITH DASHBOARD AUTO TRIGGER)
// ==========================================
onAuthStateChanged(auth, async (user) => { 
    currentUser = user; 
    // [PHASE 4.3] State sync: pull on login / stop on logout (js/14-sync.js)
    try { if (user) window.skhSyncOnLogin(user.uid); else window.skhSyncOnLogout(); } catch(e) {}
    const sidebarName = document.getElementById('sidebarUserName');
    const sidebarPic = document.getElementById('sidebarUserPic');
    const sidebarWallet = document.getElementById('sidebarWallet');
    const sidebarTokens = document.getElementById('sidebarTokens');

    if (userUnsubscribe) {
        userUnsubscribe();
        userUnsubscribe = null;
    }

    // [PHASE 2 - USALAMA] Admin role kutoka Firebase Custom Claims ( njia sahihi).
    // Inasomwa mara moja kila login; email fallback (ya chini) inaendelea kufanya kazi.
    try {
        const idTokenResult = await user.getIdTokenResult();
        window.SOKOHAI_CLAIMS = { isAdmin: idTokenResult.claims.role === 'admin' };
    } catch(claimsErr) {
        console.warn("Claims hazikusomeka:", claimsErr);
        window.SOKOHAI_CLAIMS = { isAdmin: false };
    }

    if(user) {
        if(sidebarName) sidebarName.innerText = user.displayName || "Mtumiaji";
        if(sidebarPic) sidebarPic.src = user.photoURL || `https://ui-avatars.com/api/?name=${skhEscape(user.displayName)}`;
        
        userUnsubscribe = onSnapshot(doc(db, "users", user.uid), (docSnap) => {
            if(docSnap.exists()) {
                currentUserData = { docId: docSnap.id, ...docSnap.data() };
                if(sidebarWallet) sidebarWallet.innerText = "TZS " + (currentUserData.walletBalance || 0).toLocaleString();
                if(sidebarTokens) sidebarTokens.innerText = (currentUserData.tokens || 0).toLocaleString();
                
                const spHubWallet = document.getElementById('spHubWalletBalance');
                if(spHubWallet) spHubWallet.innerText = "TZS " + (currentUserData.walletBalance || 0).toLocaleString();
                
                updateCartUI();

                // Hapa sasa tunawasha na ku-sync chati na kadi za SokoPay wallet kwa usahihi
                setTimeout(() => {
                    if (typeof window.syncSokoPayRealtimeData === 'function') {
                        window.syncSokoPayRealtimeData();
                    }
                }, 1000);

            } else {
                setDoc(doc(db, "users", user.uid), {
                    uid: user.uid, fullName: user.displayName, email: user.email,
                    walletBalance: 0, tokens: 0, createdAt: new Date().toISOString()
                });
            }
        });
    } else {
        if(sidebarName) sidebarName.innerText = "Guest User";
        if(sidebarWallet) sidebarWallet.innerText = "TZS 0";
    }
    loadMainFeed('all'); 
});

window.closeWelcome = function() { 
        const wm = document.getElementById('welcomeModal');
        if(wm) wm.style.display = 'none'; 
    };
    
    window.triggerDpUpload = function() { 
        if(!requireAuth()) return; 
        const dp = document.getElementById('dpUploadInput');
        if(dp) dp.click(); 
    };

    const dpu = document.getElementById('dpUploadInput');
    if(dpu) {
        dpu.addEventListener('change', async (e) => {
            const file = e.target.files[0]; 
            if(!file) return;
            if(file.size > 3 * 1024 * 1024) { 
                alert(" Picha ni kubwa mno, mwisho ni 3MB."); 
                return; 
            }
            
            try {
                const pic = document.getElementById('searchProfilePic');
                if(pic) pic.style.opacity = '0.5';
                
                // [PHASE 4.2] Uploader mmoja wa pamoja
                const up = await window.skhUploadFromFile(file);
                if(!up) throw new Error('Imeshindwa kupandisha picha.');
                const data = up.data;
                
                if(data.secure_url) {
                    const optImg = getOptimizedImageUrl(data.secure_url);
                    await updateProfile(currentUser, { photoURL: optImg });
                    if(currentUserData && currentUserData.docId) { 
                        await updateDoc(doc(db, "users", currentUserData.docId), { photoURL: optImg }); 
                    }
                    if(pic) pic.src = optImg; 
                    alert(" Picha yako ya Profile imebadilishwa kikamilifu!");
                }
            } catch(err) { 
                alert(" Imeshindwa kupandisha picha. Jaribu tena."); 
            } finally { 
                const pic = document.getElementById('searchProfilePic');
                if(pic) pic.style.opacity = '1'; 
            }
        });
    }

    //  NAVIGATION DATA & LOGIC

    const navMap = {
        'home': { dbCollection: 'all', title: ' Uwanja wa Mchanganyiko' },
        'bidhaa': { dbCollection: 'products', title: ' Bidhaa Zote Sokoni' },
        'services': { dbCollection: 'services', title: ' Wataalamu na Huduma' },
        'delivery': { dbCollection: 'drivers', title: ' Vyombo vya Usafiri na Mizigo' },
        'ajira': { dbCollection: 'jobs', title: ' Fursa za Kazi na Ajira' }
    };

window.openUserPaymentModal = function() {
    if(!requireAuth()) return; // Hii inazuia watumiaji ambao hawajaingia
    window.closeModals();
    const pm = document.getElementById('userPaymentModal');
    if(!pm) return;
    
    pm.style.display = 'flex';

    const btnSave = document.getElementById('btnSavePaymentAccount');
    const btnEdit = document.getElementById('btnEditPaymentAccount');
    const allInputs = pm.querySelectorAll('input, select');

    if (currentUserData && currentUserData.paymentAccount && currentUserData.paymentAccount !== "") {
        // Ipo: Honey Mode (Locked)
        allInputs.forEach(inp => {
            inp.disabled = true;
            inp.style.opacity = '0.8';
        });
        document.getElementById('paySetupType').value = currentUserData.paymentType || 'Mobile';
        setTimeout(() => { window.togglePaymentSetupFields(); }, 100);
        if(btnEdit) { btnEdit.style.display = 'block'; btnEdit.style.background = '#D4AF37'; }
        if(btnSave) btnSave.style.display = 'none';
    } else {
        // Mpya: Blue Mode (Open)
        allInputs.forEach(inp => {
            inp.disabled = false;
            inp.style.opacity = '1';
        });
        if(btnEdit) { btnEdit.style.display = 'none'; }
        if(btnSave) { btnSave.style.display = 'block'; btnSave.style.background = '#00509d'; }
    }
    // Inasoma na kupakia miamala ya SokoPay ya mtumiaji
    window.loadUserSokoPayLinks();
};

