// 1. Jaza kategoria kuu kwenye Form (Smart Sorting kulingana na Wasifu wa Duka)
window.populateFormCategories = function() {
    const catSelect = document.getElementById('prodCategory');
    if(!catSelect) return;

    // Wasifu mkuu wa duka la mtumiaji (k.m. Pharmacy, Hardware, nk)
    const primaryProfile = currentUserData?.primaryProfile || 'General Store';
    
    // Ramani inayounganisha Wasifu wa Duka na Kategoria za Bidhaa zenye uhusiano
    const profileMap = {
        'Pharmacy': ["Afya (Health)", "Urembo (Beauty)"],
        'Hardware Store': ["Ujenzi (Construction)", "Mabati na Vyuma (Industrial)", "Zana za Viwandani (Hardware)", "Spea (Spare Parts)"],
        'Grocery Store': ["Vyakula na Vinywaji (Food)", "Vyombo vya Plastiki (Retail)", "Jumla (Wholesale Goods)"],
        'Supermarket': ["Vyakula na Vinywaji (Food)", "Vyombo vya Plastiki (Retail)", "Urembo (Beauty)", "Mavazi (Fashion)"],
        'Mini Market': ["Vyakula na Vinywaji (Food)", "Vyombo vya Plastiki (Retail)"],
        'Agrovet': ["Kilimo (Agriculture)", "Ufugaji (Livestock)", "Uvuvi (Fisheries)"],
        'Phone Shop': ["Simu (Phones)", "Kompyuta (Computers)", "Mifumo (Digital Products)"],
        'Computer Store': ["Kompyuta (Computers)", "Simu (Phones)", "Mifumo (Digital Products)"],
        'Boutique': ["Mavazi (Fashion)", "Urembo (Beauty)"],
        'Shoe Store': ["Mavazi (Fashion)", "Mitumba (Second Hand)"]
    };

    const recommendedCats = profileMap[primaryProfile] || [];
    
    let recommendedHtml = '';
    let otherHtml = '';

    for (const catName in advancedCategories) {
        if (recommendedCats.includes(catName)) {
            // Zile zenye uhusiano zinawekwa hapa zikiwa na alama ya nyota
            recommendedHtml += `<option value="${catName}" style="font-weight:bold; color:var(--green);"> Mapendekezo: ${catName}</option>`;
        } else {
            // Kategoria zingine zote za soko zinawekwa hapa chini
            otherHtml += `<option value="${catName}">${catName}</option>`;
        }
    }

    catSelect.innerHTML = `
        <option value="">-- Chagua Kategoria --</option>
        ${recommendedHtml ? `<optgroup label=" Inapendekezwa kwa ajili ya ${primaryProfile}">${recommendedHtml}</optgroup>` : ''}
        <optgroup label=" Kategoria Zingine za Sokohai">${otherHtml}</optgroup>
    `;
};

// 2. Jaza Sub-categories pindi Kategoria kuu ikichaguliwa

// 3. Jaza Universal Filters (Mfano: Rangi, Ukubwa, nk)
window.generateSellerFilters = function() {
    const catVal = document.getElementById('prodCategory').value;
    const subVal = document.getElementById('prodSubCategory').value;
    const filterContainer = document.getElementById('dynamicFiltersContainer');
    const filtersArea = document.getElementById('filtersInputsArea');

    if(!subVal || !advancedCategories[catVal].subcategories[subVal]) {
        filterContainer.style.display = 'none';
        return;
    }

    const filters = advancedCategories[catVal].subcategories[subVal].filters;
    if(filters && filters.length > 0) {
        let inputsHtml = '';
        filters.forEach(f => {
            inputsHtml += `
            <div style="margin-bottom:12px;">
                <label style="font-size:11px; font-weight:bold; color:#64748b;">${f} *</label>
                <input type="text" class="universal-filter-input" data-filter="${f}" placeholder="Ingiza ${f}..." style="width:100%; padding:10px; border-radius:8px; border:1px solid #cbd5e1; background:white;">
            </div>`;
        });
        filtersArea.innerHTML = inputsHtml;
        filterContainer.style.display = 'block';
    } else {
        filterContainer.style.display = 'none';
    }
};

// 4. Badili Logic ya Kusave Bidhaa ili ichukue pia hizi Filters
const originalSubmitSeller = window.submitSeller;

window.toggleModeFields = function() {
    const mode = document.getElementById('prodSaleMode').value;
    const container = document.getElementById('dynamicModeFields');
    const auctionF = document.getElementById('mode_auction_fields');
    const dropF = document.getElementById('mode_price_drop_fields');
    const bulkF = document.getElementById('mode_bulk_fields');
    const pLabel = document.getElementById('priceLabel');

    // Ficha zote kwanza
    container.style.display = 'block';
    auctionF.style.display = 'none';
    dropF.style.display = 'none';
    bulkF.style.display = 'none';

    if (mode === 'free_market') {
        container.style.display = 'none';
        pLabel.innerText = "Bei ya Kawaida (TSh) *";
    } else if (mode === 'auction') {
        auctionF.style.display = 'block';
        pLabel.innerText = "Dau la Kuanzia (TSh) *";
    } else if (mode === 'price_drop') {
        dropF.style.display = 'block';
        pLabel.innerText = "Bei ya Kuanzia (TSh) *";
    } else {
        bulkF.style.display = 'block';
        pLabel.innerText = "Bei ya Reja reja (TSh) *";
    }
};

