    let isRecording = false;

window.toggleVoiceRecord = async function() {
    const btn = document.getElementById('voiceBtn');
    
    if(!isRecording) { 
        try {
            // 1. Omba ruhusa ya Microphone kwa mtumiaji
            const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
            mediaRecorder = new MediaRecorder(stream);
            audioChunks =[];
            
            mediaRecorder.ondataavailable = event => {
                if (event.data.size > 0) audioChunks.push(event.data);
            };
            
            mediaRecorder.onstop = async () => {
                // 3. Rekodi ikisimama, ipandishe Cloudinary
                btn.innerText = "";
                const audioBlob = new Blob(audioChunks, { type: 'audio/webm' });
                
                // [PHASE 4.2] Uploader mmoja (audio inapanda kama 'video' resource)
                try {
                    const up = await window.skhUploadFromFile(audioBlob, { resourceType: 'video' });
                    const data = up ? up.data : {}; 
                    
                    if(data.secure_url) { 
                        // Tuma url ya Sauti kwenye Firebase Chats
                        let receiverEmail = currentOpenProduct ? currentOpenProduct.userEmail : chatPartner + "@gmail.com"; // Fallback logic
                        await addDoc(collection(db, "chats"), { 
                            text: ` Attachment: ${data.secure_url}`, 
                            sender: currentUser.email, 
                            receiver: receiverEmail, 
                            createdAt: new Date().toISOString() 
                        }); 
                    }
                } catch(err) {
                    alert("Imeshindwa kutuma Voice Note.");
                } finally {
                    btn.style.color = "var(--terracotta)"; 
                    btn.innerText = ""; 
                }
            };
            
            // 2. Anza kurekodi
            mediaRecorder.start();
            isRecording = true; 
            btn.style.color = "red"; 
            btn.innerText = ""; 
            alert(" Inarekodi sauti... Bofya tena kutuma.");
            
        } catch (err) {
            alert(" Ruhusu simu/browser kutumia Microphone yako ili uweze kutuma Sauti.");
        }
    } else { 
        // Simamisha Kurekodi
        mediaRecorder.stop();
        isRecording = false; 
    }
};
        
