    function updateSliders(dataArray) {
        if (!dataArray || dataArray.length === 0) return;
        const renderHTML = (arr) => arr.map(data => {
            const optImgUrl = getOptimizedImageUrl(data.image || data.photo || window.SKH_PLACEHOLDER_IMG); // [PHASE 5.7]
            const formattedPrice = data.price ? `TSh ${data.price.toLocaleString()}` : (data.jobType || 'Maelewano');
            const itemTitle = data.title || data.company || 'Tangazo';
            const isBoosted = data.isBoosted ? `<div class="boost-badge"> BOOSTED</div>` : '';
            return `<div class="large-card" onclick="openProduct('${data.id}')">${isBoosted}<div class="card-img skeleton" style="position:relative; overflow:hidden;"><img src="${skhEscape(optImgUrl)}" loading="lazy" style="width:100%; height:100%; object-fit:contain; background:#fff; border-radius:10px;" // [PHASE 6.0] onload="this.parentElement.classList.remove('skeleton')" onerror="this.src=window.SKH_PLACEHOLDER_IMG||'https://ui-avatars.com/api/?name=Soko&background=f1f5f9&color=64748b'"></div><b style="font-size:12px; white-space:nowrap; overflow:hidden; text-overflow:ellipsis; margin-top:8px;">${skhJsEsc(itemTitle)}</b><span style="color:var(--green);font-size:13px;font-weight:900; margin-top:2px;">${formattedPrice}</span><small style="font-size:10px; color:#64748b; margin-top:4px; white-space:nowrap; overflow:hidden; text-overflow:ellipsis;">${window.skhNavIcon ? skhNavIcon('map', 10) : ''} ${skhEscape(data.location || data.route || 'Online')}</small></div>`;
        }).join('');
        
        const sl1 = document.getElementById('slider1');
        const sl2 = document.getElementById('slider2');
        const sl3 = document.getElementById('slider3');
        
        if(sl1) sl1.innerHTML = renderHTML(dataArray.filter(d => d.isBoosted).concat(dataArray).slice(0, 6)); 
        if(sl2) sl2.innerHTML = renderHTML(dataArray.length > 4 ? dataArray.slice(2, 8) : dataArray);
        if(sl3) sl3.innerHTML = renderHTML(dataArray.length > 6 ? dataArray.slice(4, 10) : dataArray);
    }

