// 1. UPDATE TOGGLE SYSTEM (Hifadhi Kweli Firebase)
window.toggleSys = async function(category, feature) {
    if(!sysConfig[category]) sysConfig[category] = {};
    
    // Switch logic
    sysConfig[category][feature] = !sysConfig[category][feature];
    
    try {
        const configRef = doc(db, "system", "config");
        // Tunatumia setDoc na merge:true ili kama doc haipo itengenezwe
        await setDoc(configRef, sysConfig, { merge: true });
        
        console.log(`Mabadiliko: ${category} ${feature} sasa ni ${sysConfig[category][feature]}`);

        //  Alert System ikizimwa/kuwashwa, lazimisha Announcement Bar ibadilike PAPO HAPO
        // badala ya kusubiri snapshot ijayo ya matangazo.
        if(category === 'alerts' && feature === 'active' && typeof window.updateLiveTicker === 'function') {
            window.updateLiveTicker('normal', '', '', true);
        }

        loadAdminDashboard(); // Refresh UI ya admin
    } catch(e) {
        console.error("Error saving config:", e);
        alert(" Imeshindwa kusave mabadiliko kwenye Firebase.");
    }
};

// 2. REAL-TIME LISTENER (Iwekwe juu ya onAuthStateChanged)
window.skhOnSnapshot('system-config', doc(db, "system", "config"), (docSnap) => {
    if(docSnap.exists()) {
        const prevAlertsActive = sysConfig?.alerts?.active !== false;
        sysConfig = docSnap.data();
        window.sysConfig = sysConfig; // ipatikane globally kwa engine ya announcement bar
        console.log("Config imesomwa upya:", sysConfig);

        const newAlertsActive = sysConfig?.alerts?.active !== false;
        // Alert System ikizimwa na admin mwingine popote, watumiaji wote wabadilike papo hapo.
        if(prevAlertsActive && !newAlertsActive && typeof window.updateLiveTicker === 'function') {
            window.updateLiveTicker('normal', '', '', true);
        }
    }
});

// ==========================================================
//  SOKOHAI ANNOUNCEMENT BAR MANAGER (Firestore Live-Sync)
// Admin anaweza kuongeza/kuhariri/kufuta matangazo bila kugusa code.
// Watumiaji wote wanaona mabadiliko papo hapo (real-time sync).
// ==========================================================
window.__sokohaiAnnouncementsCache = [];
window.__sokohaiAnnouncementsUnsub = null;

window.sokohaiStartAnnouncementsListener = function(){
    if(window.__sokohaiAnnouncementsUnsub) return; // tayari inasikiliza
    try {
        const annQ = query(collection(db, "announcements"), orderBy("createdAt", "desc"));
        window.__sokohaiAnnouncementsUnsub = onSnapshot(annQ, (snap) => {
            const all = [];
            snap.forEach(docSnap => all.push({ id: docSnap.id, ...docSnap.data() }));
            window.__sokohaiAnnouncementsCache = all;
            if(typeof window.__sokohaiOnAnnouncementsUpdate === 'function') {
                window.__sokohaiOnAnnouncementsUpdate(all);
            }
            if(typeof window.renderAnnouncementManagerList === 'function') {
                window.renderAnnouncementManagerList();
            }
        }, (err) => console.error("Announcements listener error:", err));
    } catch(e) { console.error("Imeshindwa kuanzisha listener ya matangazo:", e); }
};

window.sokohaiSaveAnnouncement = async function(payload, editId){
    try {
        const data = {
            text: String(payload.text || '').trim(),
            icon: String(payload.icon || '').trim(),
            type: payload.type || 'normal',
            link: String(payload.link || '').trim(),
            startAt: payload.startAt || '',
            endAt: payload.endAt || '',
            active: payload.active !== false,
            updatedAt: new Date().toISOString()
        };
        if(editId) {
            await updateDoc(doc(db, "announcements", editId), data);
        } else {
            data.createdAt = new Date().toISOString();
            await addDoc(collection(db, "announcements"), data);
        }
        return true;
    } catch(e) {
        console.error("Kosa kuhifadhi tangazo:", e);
        alert(" Imeshindwa kuhifadhi tangazo: " + e.message);
        return false;
    }
};

