window.registerOfflineMember = async function() {
    if(!requireAuth() || !currentUserData || !currentUserData.isApprovedAgent) {
        alert(" Hamna idhini ya kutumia usajili wa mawakala.");
        return;
    }

    const name = document.getElementById('offName').value.trim();
    let phone = document.getElementById('offPhone').value.trim();
    const region = document.getElementById('offRegion').value.trim();
    const district = document.getElementById('offDistrict').value.trim();
    const bType = document.getElementById('offBusinessType').value;
    let payPhone = document.getElementById('offPayPhone').value.trim();

    if(!name || !phone || !region || !district || !payPhone) {
        alert(" Tafadhali jaza sehemu zote zenye alama ya nyota (*)."); 
        return;
    }

    const btn = document.getElementById('btnOffline');
    const origText = btn.innerHTML;
    btn.innerHTML = " INAPROSESI ADA TSH 2,100...";
    btn.disabled = true;

    try {
        if(payPhone.startsWith('0')) payPhone = '255' + payPhone.substring(1);
        // [PHASE 4.2b] Malipo ya ada — AzamPay moja (simulation inatawaliwa na DEMO_MODE)
        const pay = await window.skhAzamPayMno({ phone: payPhone, amount: 2100, externalId: "OFFREG_" + Date.now() });
        if (!pay.ok) {
            throw new Error("Malipo ya ada ya TSh 2,100 yamefeli. Hakikisha laini yako ina salio la kutosha.");
        }
        let transId = pay.transactionId;

        // Kupandisha picha ya hiari Cloudinary
        let photoUrl = "";
        const photoInput = document.getElementById('offPhoto');
        if (photoInput && photoInput.files && photoInput.files[0]) {
            btn.innerHTML = " INAPANDISHA PICHA YA MTEJA...";
            photoUrl = await uploadImage('offPhoto') || "";
        }

        // Kuzalisha IDs za kipekee kulingana na muundo uliotajwa
        const randomDigits = Math.floor(100000 + Math.random() * 900000); // Tarakimu 6 za bahati
        let offlineAccountId = `SOH-OF-${randomDigits}`;
        let businessId = null;
        let businessSetupComplete = false;

        if (bType !== "Sio Biashara") {
            businessId = `BUS-${randomDigits}`;
            businessSetupComplete = true;
        }

        // Kutengeneza barua pepe na nenosiri la siri kiotomatiki kwa kuwa hawana smartphone
        const email = `offline_${randomDigits}@sokohai.com`;
        const defaultPassword = `sokohai${randomDigits}`;

        btn.innerHTML = " INASAJILI SYSTEM CREDENTIALS...";
        const signUpUrl = `https://identitytoolkit.googleapis.com/v1/accounts:signUp?key=${firebaseConfig.apiKey}`;
        const regRes = await fetch(signUpUrl, {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ email: email, password: defaultPassword, returnSecureToken: false })
        });
        const regData = await regRes.json();
        
        if(regData.error) throw new Error(regData.error.message);
        const newUid = regData.localId;

        btn.innerHTML = " INAHIFADHI HISTORIA CODES...";
        // Kuhifadhi mtumiaji offline katika users collection
        await setDoc(doc(db, "users", newUid), {
            uid: newUid,
            fullName: name,
            phone: phone,
            email: email,
            photoURL: photoUrl || `https://ui-avatars.com/api/?name=${encodeURIComponent(name)}&background=f1f5f9&color=64748b`,
            region: region,
            district: district,
            businessType: bType,
            isOfflineUser: true,
            offlineAccountId: offlineAccountId,
            businessId: businessId,
            businessSetupComplete: businessSetupComplete,
            shopName: bType !== "Sio Biashara" ? `Duka la ${name}` : null,
            managedByAgentUid: currentUser.uid,
            managedByAgentName: currentUser.displayName || "Wakala",
            agentCode: currentUserData.myAgentCode,
            walletBalance: 0,
            createdAt: new Date().toISOString()
        });

        // Kumpatia Wakala kamisheni yake ya papo hapo ya 60% (TSh 1,260)
        // [PHASE 5.2b] kituo kimoja — skhWalletAdjust (legacy 1:1 geti likiwa off; server+ledger ikiwa on)
        await window.skhWalletAdjust(doc(db, "users", currentUserData.docId), 1260, { type: 'commission', ledgerKey: 'offreg_' + newUid, note: 'Kamisheni ya wakala - usajili wa mwanachama' });

        // Kuhifadhi 40% (TSh 840) kama mapato ya system
        await addDoc(collection(db, "adminRevenue"), {
            type: "offline_registration",
            amount: 840,
            agentCode: currentUserData.myAgentCode,
            date: new Date().toISOString()
        });

        alert(` USAJILI UMEKAMILIKA!\n\nID ya Mteja: ${offlineAccountId}\n${businessId ? `ID ya Biashara: ${businessId}\n` : ''}Mteja amesajiliwa kikamilifu.\n\nTSh 1,260 imewekwa kwenye Wallet yako kama kamisheni ya uwakala.`);
        
        document.getElementById('offlineMemberForm').reset();
        closeModals();
        loadAgentDashboard();

    } catch (error) {
        alert(" Kosa wakati wa usajili: " + error.message);
    } finally {
        btn.innerHTML = origText;
        btn.disabled = false;
    }
};

// Usajili wa Wakala (Ada 3,100) - TOLEO LA PRO MAX (Verified Malipo)
window.submitAgentFromDash = async function() {
    if(!requireAuth()) return;

    const name = document.getElementById('dashAgentName').value.trim();
    let phone = document.getElementById('dashAgentPhone').value.trim();
    const region = document.getElementById('dashAgentRegion').value;
    
    if(!name || !phone || !region) {
        alert(" Tafadhali jaza Jina, Simu, na Mkoa kabla ya kuendelea."); 
        return;
    }

    // 1. Maandalizi ya Malipo
    if(phone.startsWith('0')) phone = '255' + phone.substring(1);
    const txRef = "AGT_" + Date.now(); // Hii ndio namba ya kumbukumbu ya muamala

    const btn = document.getElementById('btnDashAgent');
    const originalText = btn.innerHTML;
    btn.innerHTML = " INASINDIKA MALIPO...";
    btn.disabled = true;
    
    try {
        // 2. JARIBU KULIPIA KWANZA (AzamPay USSD Push) — [PHASE 4.2b] AzamPay moja
        const payData = await window.skhAzamPayMno({ phone: phone, amount: 3100, externalId: txRef, strict: true });


        // 3. IKIWA OMBI LA MALIPO LIMETUMWA KWENYE SIMU
        if (payData.ok) {
            
            // 4. HIFADHI DATA FIREBASE (Ikiwa imefungwa na namba ya kumbukumbu)
            await addDoc(collection(db, "agents"), {
                userId: currentUser.uid,
                userEmail: currentUser.email,
                fullName: name,
                contact: phone,
                location: region,
                status: "pending",
                paymentRef: txRef, // MUHIMU: Kwa ajili ya uhakiki wa admin
                isPaid: false, // Itakuwa true admin akihakiki pesa
                createdAt: new Date().toISOString()
            });

            // 5. REKODI MAPATO YA ADMIN (Pending Verification)
            await addDoc(collection(db, "adminRevenue"), { 
                type: "agent_registration", 
                amount: 3100, 
                paymentRef: txRef,
                userEmail: currentUser.email,
                date: new Date().toISOString() 
            });

            alert(` Kikaratasi cha malipo kimetumwa kwenye simu yako (${phone}).\n\nWeka PIN kukamilisha usajili wa TSh 3,100. Baada ya hapo, Admin atathibitisha akaunti yako.`);
            
            // Funga kioo na urudishe dashboard
            closeModals();
            loadAndRenderDashboard();

        } else {
            // Ikiwa AzamPay imekataa namba au ina tatizo
            alert(" AzamPay imeshindwa kutuma ombi la malipo: " + (payData.data?.message || payData.error || "Angalia namba ya simu."));
        }

    } catch(e) {
        console.error("Agent Registration Error:", e);
        // Hapa tunatoa alert ya kosa la kimtandao au Firebase
        alert(" Hitilafu imetokea: " + e.message);
    } finally {
        btn.innerHTML = originalText;
        btn.disabled = false;
    }
};

