// =====================================================
// 2. MFUMO WA MALIPO YA VIFURUSHI (REAL PAYMENT LOGIC)
// =====================================================
window.paySubscription = async function(amount, title) {
  let catKey = (currentMode === 'provider') ? 'huduma' : ((currentMode === 'employer') ? 'ajira' : 'bidhaa');
    const isFreeMode = (sysConfig && sysConfig[catKey] && sysConfig[catKey].sub === false);
    if(!requireAuth()) return;
    
// Mfumo unavuta namba iliyosaviwa
    let payPhone = currentUserData.paymentAccount || currentUserData.phone;
    if(!payPhone) {
        alert(" Tafadhali sajili Namba yako ya Malipo kwenye Akaunti kwanza.");
        openUserPaymentModal();
        return;
    }

    if(!confirm(`Je, unathibitisha kulipia Kifurushi cha ${title} (TSh ${amount.toLocaleString()}) kupitia namba yako: ${payPhone}?`)) return;

    // Format namba iwe 255...
    if(payPhone.startsWith('0')) payPhone = '255' + payPhone.substring(1);

    closeModals();
    alert(` Ombi la malipo limetumwa kwenye namba ${payPhone}. Tafadhali weka PIN kukamilisha.`);
    
    try {
        // A. Tengeza tarehe ya ku-expire (Siku 30 au 365)
        const subExpiryDate = new Date();
        if(title.toLowerCase().includes('year')) {
            subExpiryDate.setFullYear(subExpiryDate.getFullYear() + 1);
        } else {
            subExpiryDate.setMonth(subExpiryDate.getMonth() + 1);
        }

        // B. SAVE KWENYE FIREBASE (Hifadhi kwanza ili hata AzamPay ikileta delay data ipo)
        if(currentUserData && currentUserData.docId) {
            await updateDoc(doc(db, "users", currentUserData.docId), { 
                isSubscribed: true,
                subscriptionType: title,
                subscriptionValidUntil: subExpiryDate.toISOString(),
                subStatus: "Active"
            });
        }

        // C. REKODI MAPATO YA ADMIN
        await addDoc(collection(db, "adminRevenue"), { 
            type: "subscription", 
            amount: amount, 
            package: title,
            userEmail: currentUser.email,
            date: new Date().toISOString() 
        });
// D. TUMA OMBI AZAMPAY AU IFANYE BURE
        if (isFreeMode) {
            alert(` Mfumo upo wazi BURE kwa sasa! Kifurushi chako cha ${title} kimeamilishwa.`);
            loadAndRenderDashboard();
            return; // Usiende AzamPay
        }

        try {
            // [PHASE 4.2b] AzamPay moja (fire-and-forget kama ilivyokuwa)
            await window.skhAzamPayMno({ phone: payPhone, amount: amount, externalId: "SUB_" + Date.now() });
        } catch(azamErr) {
            console.warn("AzamPay API Simulation Note: Ikiwa unatumia Localhost/Browser, malipo yanasave Firebase lakini yanazuiliwa na CORS (Hii ni kawaida mpaka uwe na Backend).");
        }

        alert(` Hongera! Kifurushi cha ${title} kimeamilishwa. Muda wa kuisha: ${subExpiryDate.toLocaleDateString()}`);
        loadAndRenderDashboard(); // Refresh Dashboard kuonyesha status mpya

    } catch(e) {
        alert(" Imeshindwa kuamilisha kifurushi. Kosa: " + e.message);
    }
};

