                        { label: 'Stock In', data: [100, 150, 80, 220, 190, 310], borderColor: '#10b981', fill: false },
                        { label: 'Stock Out', data: [40, 80, 50, 120, 110, 180], borderColor: '#ef4444', fill: false }
