// --- SOKOHAI LIVE TICKER / PROFESSIONAL ANNOUNCEMENT ENGINE ---
// NOTE: The actual moving marquee engine (with Firestore admin sync, Read More links,
// and smooth animation) lives near the end of <body> in the script tagged
// "sokohaiProfessionalAnnouncementFinalJS". It defines window.updateLiveTicker,
// window.startSokoHaiAnnouncementRotator, etc. We intentionally do NOT redefine
// those functions here anymore — doing so previously overwrote the moving marquee
// with a static, non-animated version because this module script runs after that
// plain <script> tag (deferred module execution order), causing the "text not moving" bug.

// ==========================================================
// ==========================================================
// ==========================================================
// 1. GLOBAL SETTINGS & UTILS
// ==========================================================

// Kazi ya kupiga hesabu ya umbali (Km) kati ya watu wawili
function calculateDistance(lat1, lon1, lat2, lon2) {
    const R = 6371; // Radius ya dunia
    const dLat = (lat2 - lat1) * Math.PI / 180;
    const dLon = (lon2 - lon1) * Math.PI / 180;
    const a = Math.sin(dLat/2) * Math.sin(dLat/2) +
              Math.cos(lat1 * Math.PI / 180) * Math.cos(lat2 * Math.PI / 180) * 
              Math.sin(dLon/2) * Math.sin(dLon/2);
    const c = 2 * Math.atan2(Math.sqrt(a), Math.sqrt(1-a));
    return R * c; 
}

// Kazi ya kupata jina la mtaa/Block (Reverse Geocoding)
async function getAddressName(lat, lon) {
    try {
        const res = await fetch(`https://nominatim.openstreetmap.org/reverse?format=json&lat=${lat}&lon=${lon}`);
        const data = await res.json();
        return data.display_name || "Eneo lisilojulikana";
    } catch (e) { return "Eneo la Tukio"; }
}


// ==========================================================
//  SOKOHAI MASTER MONITOR (PRIORITY ENGINE)
// ==========================================================
function startMasterMonitoring() {
    // [SOKOHAI] Live Business Ticker: minada, bei kushuka, group buy.
    // Alert System ya Admin (sysConfig.alerts) inadhibiti bar nzima.
    const alertSystemOn = sysConfig?.alerts?.active !== false;
    if (!alertSystemOn) {
        window.updateLiveTicker('normal', '');
        return;
    }

// D. Kagua mienendo ya minada, bei kushuka, au group buy zilizo hai (ambazo muda wake haujaisha bado)
                const qActivities = query(collection(db, "products"), where("saleMode", "in", ["auction", "price_drop", "group_buy"]));
                getDocs(qActivities).then(actSnap => {
                    let activeActivityFound = false;
                    const nowMs = Date.now();

                    if (!actSnap.empty) {
                        // Pitia bidhaa kupata ile ambayo muda wa mnada wake bado haujaisha
                        for (let doc of actSnap.docs) {
                            const act = doc.data();
                            const mData = act.modeData || {};
                            const endTime = mData.endTime || 0;

                            // Ikiwa muda wa kuisha upo mbele (haujaisha bado), ionyeshe live kwenye upau wa juu
                            if (nowMs < endTime) {
                                window.updateLiveTicker(act.saleMode, '', act.title);
                                activeActivityFound = true;
                                break; // Komesha loop baada ya kupata ya kwanza iliyo hai sokoni
                            }
                        }
                    }

                    // Ikiwa hakuna mnada, price drop au group buy iliyo hai kwa sasa, weka tangazo la kawaida
                    if (!activeActivityFound) {
                        window.updateLiveTicker('normal', '');
                    }
                }).catch(() => {
                    window.updateLiveTicker('normal', '');
                });
}


