// 1. MFUMO WA KUVUTA MATANGAZO (REFIXED UI)
// ==========================================

// Imerekebishwa: Safe & Robust Feed Loader (Inazuia Firebase Composite Index errors)
window.loadMainFeed = async function(collectionToFetch = 'products') {
    const feedGrid = document.getElementById('mainFeed'); 
    if(!feedGrid) return;
    
    feedGrid.innerHTML = `
        <div style="grid-column: 1/-1; text-align:center; padding:50px 0;">
            <div style="display:inline-block; width:30px; height:30px; border:3px solid #f3f3f3; border-top:3px solid #03509d; border-radius:50%; animation: spin 1s linear infinite;"></div>
            <p style="color:#64748b; font-size:13px; margin-top:10px;">Inapakia...</p>
        </div>`;
    
    if(window.unsubscribeFeed) window.unsubscribeFeed();

    // Mchanganyiko wa Home Page
    if (collectionToFetch === 'all') {
        Promise.all([
            getDocs(query(collection(db, 'products'), limit(20))),
            getDocs(query(collection(db, 'services'), limit(10))),
            getDocs(query(collection(db, 'jobs'), limit(10))),
            getDocs(query(collection(db, 'drivers'), limit(10)))
        ]).then(results => {
            let combinedData = [];
            results.forEach((snap, index) => {
                const colNames = ['products', 'services', 'jobs', 'drivers'];
                snap.forEach(doc => {
                    combinedData.push({ id: doc.id, collectionName: colNames[index], ...doc.data() });
                });
            });
            // Kupanga mpya juu kwanza
            combinedData.sort((a,b) => new Date(b.createdAt || 0) - new Date(a.createdAt || 0));
            cachedItems = combinedData; 
            renderFeedUI(combinedData, feedGrid);
        }).catch(err => {
            console.error(err);
            feedGrid.innerHTML = `<p style="text-align:center; padding:20px; color:red;">Kosa kupakia feed.</p>`;
        });
        return;
    }

    let qNormal;
    const currentActiveMode = activeMarketMode;

    try {
        if (currentActiveMode !== "all_modes" && collectionToFetch === 'products') {
            qNormal = query(collection(db, collectionToFetch), where("saleMode", "==", currentActiveMode), limit(currentLimit));
        } else if (activeCategory !== "Zote" && activeCategory !== "") {
            qNormal = query(collection(db, collectionToFetch), where("category", "==", activeCategory), limit(currentLimit));
        } else {
            qNormal = query(collection(db, collectionToFetch), limit(currentLimit));
        }

        window.unsubscribeFeed = onSnapshot(qNormal, (snapshot) => {
            let normalData = snapshot.docs.map(doc => ({ id: doc.id, collectionName: collectionToFetch, ...doc.data() }));
            normalData.sort((a,b) => new Date(b.createdAt || 0) - new Date(a.createdAt || 0));
            renderFeedUI(normalData, feedGrid);
        }, (error) => {
            console.error(error);
            // Fallback ya usalama kama kosa limetokea
            const fallbackQuery = query(collection(db, collectionToFetch), limit(currentLimit));
            getDocs(fallbackQuery).then(snapshot => {
                let normalData = snapshot.docs.map(doc => ({ id: doc.id, collectionName: collectionToFetch, ...doc.data() }));
                renderFeedUI(normalData, feedGrid);
            });
        });
    } catch (e) {
        console.error(e);
    }
};

