window.payStaffSalary = async function(staffDocId, fullSalary) {
    let payAmountPrompt = prompt(` INALIPA KWA SOKOPAY:\nMshahara Kamili: TSh ${fullSalary.toLocaleString()}\n\nIngiza kiasi unachotaka kumlipa (Unaweza kumlipa nusu au wote):`, fullSalary);
    if (!payAmountPrompt) return;

    const amountToPay = parseFloat(payAmountPrompt);
    if (isNaN(amountToPay) || amountToPay <= 0 || amountToPay > fullSalary) {
        alert(" Kiasi cha malipo si sahihi au kimezidi mshahara!");
        return;
    }

    const payPhone = currentUserData.paymentAccount || currentUserData.phone;
    if (!payPhone) {
        alert(" Tafadhali sajili Namba yako ya kupokelea/kutolea pesa kwenye menyu ya malipo kwanza.");
        return;
    }

    alert(` SokoPay USSD Push inatumwa kwa namba yako ya kulipia (${payPhone}) ili kutoa TSh ${amountToPay.toLocaleString()}. Weka PIN ya simu kuthibitisha.`);

    try {
        // [PHASE 4.2b] AzamPay moja (fire-and-forget kama ilivyokuwa)
        await window.skhAzamPayMno({ phone: payPhone, amount: amountToPay, externalId: "PAYROLL_" + Date.now() });

        const staffRef = doc(db, "shop_staff", staffDocId);
        const staffSnap = await getDoc(staffRef);
        if (staffSnap.exists()) {
            const currentPaid = parseFloat(staffSnap.data().paidSalary || 0);
            const totalPaidNow = currentPaid + amountToPay;

            await updateDoc(staffRef, {
                paidSalary: totalPaidNow,
                pendingSalary: fullSalary - totalPaidNow
            });

            const ownerUid = currentUserData?.shopOwnerUid || currentUser.uid;
            await addDoc(collection(db, "shop_ledger"), {
                shopOwnerId: ownerUid,
                type: "expense",
                title: `Mshahara: ${staffSnap.data().name} (SokoPay)`,
                amount: amountToPay,
                date: new Date().toISOString()
            });
        }

        alert(" Malipo ya SokoPay yamefanikiwa! Mfanyakazi amebadilishiwa status kuwa PAID/PARTIAL.");
        loadAndRenderDashboard();

    } catch (e) {
        alert(" Hitilafu ya malipo: " + e.message);
    }
};

