window.verifyHandoverToken = async function(rideId, stage) {
    const rideRef = doc(db, "ride_requests", rideId);
    const docSnap = await getDoc(rideRef);
    
    if(!docSnap.exists()) return alert(" Hitilafu: Ombi la usafiri halijapatikana!");
    const rd = docSnap.data();

    if (stage === 'pickup') {
        // --- 1. PICKUP STAGE (TOKEN A - PK) ---
        const inputPK = document.getElementById(`pickupTokenInp_${rideId}`).value.trim().toUpperCase();
        if(inputPK !== rd.pickupToken) {
            alert(" Token uliyoweka SI sahihi! Dereva, mwombe muuzaji akupe Token A sahihi kutoka kwenye duka lake.");
            return;
        }
        
        // Uhakiki wa Mifugo ikiwa amebeba wanyama
        let startCount = rd.animalCount || 0;
        if(rd.reqCategory === 'Livestock') {
            const verifiedCount = prompt(` LIVE COUNT VERIFICATION:\nIdadi iliyotajwa kwenye oda: ${startCount} Heads.\n\nThibitisha idadi halisi unayopakia hivi sasa kwenye gari:`, startCount);
            if(verifiedCount === null) return;
            startCount = parseInt(verifiedCount) || startCount;
            await updateDoc(rideRef, { verifiedPickupCount: startCount });
        }

        // Badili status ya safari kuwa ipo njiani (in_transit)
        await updateDoc(rideRef, { 
            status: "in_transit",
            dispatchedAt: new Date().toISOString()
        });

        alert(" UHAKIKI UMEFANIKIWA!\nMzigo umeruhusiwa kuanza safari (In-Transit). Anza kuendesha kwa usalama.");
    } 
    else if (stage === 'delivery') {
        // --- 2. DELIVERY STAGE (TOKEN C - DL) ---
        const inputDL = document.getElementById(`deliveryTokenInp_${rideId}`).value.trim().toUpperCase();
        if(inputDL !== rd.transferCode) {
            alert(" Token uliyoweka SI sahihi! Dereva, mwombe mpokeaji wa mzigo akupe Token C (DL Code) aliyopewa kwenye simu yake.");
            return;
        }

        const finalPrice = rd.cargoPrice || rd.price || 40000; // Gharama ya usafiri

        // Uhakiki wa mwisho wa mifugo
        if(rd.reqCategory === 'Livestock') {
            const pickupCount = rd.verifiedPickupCount || rd.animalCount || 0;
            const arrivalCountPrompt = prompt(` ARRIVAL COUNT CHECK:\nIdadi iliyopakiwa mwanzo: ${pickupCount} Heads.\n\nIngiza idadi halisi ya mifugo iliyofika salama:`, pickupCount);
            if(arrivalCountPrompt === null) return;
            const arrivalCount = parseInt(arrivalCountPrompt) || 0;

            if(arrivalCount < pickupCount) {
                const lostCount = pickupCount - arrivalCount;
                const penalty = (finalPrice * 0.15) * lostCount; // Faini ya 15% kwa kila aliyepotea
                const adjustedPayout = Math.max(0, finalPrice - penalty);
                
                if(confirm(` MKATABA WA DHARURA: Mifugo ${lostCount} imepotea njiani!\n\nKiasi cha kulipwa kimepunguzwa kwa faini hadi TSh ${adjustedPayout.toLocaleString()}.\n\nJe, unakubali kupokea na kukamilisha safari?`)) {
                    await updateDoc(rideRef, { 
                        status: "completed", 
                        verifiedArrivalCount: arrivalCount, 
                        finalPayout: adjustedPayout,
                        completedAt: new Date().toISOString()
                    });
                    
                    const driverRef = doc(db, "users", currentUser.uid);
                    // [PHASE 5.2b] kituo kimoja — skhWalletAdjust (legacy 1:1 geti likiwa off; server+ledger ikiwa on)
                    await window.skhWalletAdjust(driverRef, adjustedPayout, { type: 'payout', ledgerKey: 'ridefin_' + rideRef.id, note: 'Malipo ya safari (faini ya kuchelewa)' });
                    
                    alert(` Safari imekamilishwa! Umeingiziwa TSh ${adjustedPayout.toLocaleString()} (Faini: TSh ${penalty.toLocaleString()})`);
                    window.renderDriverActiveTabContent();
                    return;
                } else {
                    // Weka kwenye dispute
                    await updateDoc(rideRef, { 
                        status: "disputed", 
                        disputeReason: `Mifugo ${lostCount} imepotea safarini. Dereva amekataa kukatwa faini ya upotevu.` 
                    });
                    alert(" Mgogoro umesajiliwa. Pesa imezuiwa kwenye Escrow hadi utatuzi wa Admin.");
                    window.renderDriverActiveTabContent();
                    return;
                }
            }
        }

        // --- UKAMILISHAJI NA UREJESHO WA FEDHA (SETTLEMENT) ---
        // 1. Badili hali ya safari kuwa imekamilika
        await updateDoc(rideRef, { 
            status: "completed",
            completedAt: new Date().toISOString()
        });

        // 2. Mpe dereva malipo yake ya usafiri kwenye Wallet
        const driverRef = doc(db, "users", currentUser.uid);
        // [PHASE 5.2b] kituo kimoja — skhWalletAdjust (legacy 1:1 geti likiwa off; server+ledger ikiwa on)
        await window.skhWalletAdjust(driverRef, finalPrice, { type: 'payout', ledgerKey: 'tokenc_' + rideRef.id, note: 'Malipo ya safari - Token C' });

        await addDoc(collection(db, "notifications"), {
            userId: currentUser.uid,
            title: " SokoPay: Malipo ya Safari Yamepokelewa!",
            body: `Mteja amethibitisha kwa Token C. TSh ${finalPrice.toLocaleString()} imeingizwa kwenye wallet yako.`,
            createdAt: new Date().toISOString(),
            read: false
        });

        // 3. AUTO-RELEASE YA BIDHAA: Tafuta na uthibitishe mkataba wa bidhaa unaoandana na safari hii
        try {
            const qOrder = query(collection(db, "orders"), where("buyerId", "==", rd.customerId), where("itemId", "==", rd.parentRideId || "N/A"), where("status", "==", "held"));
            const orderSnap = await getDocs(qOrder);
            if (!orderSnap.empty) {
                const orderDoc = orderSnap.docs[0];
                const oData = orderDoc.data();
                
                // Thibitisha oda ya bidhaa kiotomatiki kwa niaba ya mteja
                await updateDoc(doc(db, "orders", orderDoc.id), { status: "completed" });
                
                // Mlipe muuzaji wa bidhaa
                const sellerQuery = await getDocs(query(collection(db, "users"), where("uid", "==", oData.sellerId)));
                if (!sellerQuery.empty) {
                    const sellerDocId = sellerQuery.docs[0].id;
                    const platformFee = oData.amount * 0.05; // 5% fee
                    const sellerEarned = oData.amount - platformFee;

                    // [PHASE 5.2b] kituo kimoja — skhWalletAdjust (legacy 1:1 geti likiwa off; server+ledger ikiwa on)
                    await window.skhWalletAdjust(doc(db, "users", sellerDocId), sellerEarned, { type: 'escrow_release', ledgerKey: 'chain_order_' + orderDoc.id, note: 'Auto-release ya bidhaa ya safari (chain)' });
                }
                console.log("SokoPay: Bidhaa inayohusiana na usafiri huu imelipwa na kuachiliwa kwa muuzaji!");
            }
        } catch(orderErr) {
            console.log("Sio chain order ya kawaida, hakuna bidhaa ya ziada iliyoguswa.");
        }

        alert(` SAFARI IMEKAMILIKA!\nTSh ${finalPrice.toLocaleString()} imeingizwa kwenye wallet yako vizuri.`);
    }
    
    window.renderDriverActiveTabContent();
};
// Simulator kwa ajili ya muuzaji (Seller) kuthibitisha Token A ya dereva na kumkabidhi mzigo
window.simulateSellerHandover = async function(rideId) {
    const rideRef = doc(db, "ride_requests", rideId);
    const docSnap = await getDoc(rideRef);
    if (!docSnap.exists()) return;

    const rd = docSnap.data();
    
    window.customPrompt(` SELLER HANDOVER VERIFICATION\nDereva amefika! Mmiliki wa mzigo (Seller), tafadhali ingiza Token PK (${rd.pickupToken}) aliyokupa Dereva ili kumthibitisha kabla ya kukabidhi mzigo:`, "PK-XXXX", async (inputToken) => {
        if (!inputToken) return;

        if (inputToken.toUpperCase() !== rd.pickupToken) {
            alert(" Token Wrong! Mfumo umeziba handover kwa sababu namba ya utambulisho hailingani.");
            return;
        }

        // Mfumo unathibitisha na kubadili status kuwa in_transit kiotomatiki
        await updateDoc(rideRef, { 
            status: "in_transit" 
        });
alert(`✓ Driver Verified!\n\nMzigo umekabidhiwa salama kwa Dereva. Status imebadilika kuwa: SAFARINI (In Transit) `);
        // weka upya, haina haja ya loadDriverWorkspace, mzunguko wa Real-Time utasafisha kioo chenyewe!
    });
};

