// 1. KUHAKIKI MSIMBO NA KUONYESHA PREVIEW YA MKATABA (VERIFY CODE)
window.verifyAndPreviewSokoPay = async function() {
    const code = document.getElementById('spCodeInputPay').value.trim().toUpperCase();
    if (!code) {
        alert(" Tafadhali ingiza msimbo wa SokoPay (SP-XXXXXX) kwanza!");
        return;
    }

    const preview = document.getElementById('spItemPreview');
    const btnVerify = document.getElementById('btnVerifySp');
    const btnProceed = document.getElementById('btnProceedPaySp');

    if (preview) {
        preview.innerHTML = '<p style="text-align:center; color:gray; font-size:11px; padding:10px;"> Inahakiki msimbo kutoka kwenye daftari la mkataba...</p>';
        preview.style.display = 'block';
    }

    try {
        // Tafuta mkataba kwenye Firestore wenye msimbo huu na ambao haujalipiwa (status == pending)
        const q = query(collection(db, "sokopay_links"), where("code", "==", code), where("status", "==", "pending"));
        const snap = await getDocs(q);

        if (snap.empty) {
            if (preview) preview.style.display = 'none';
            alert(" Msimbo huu si sahihi, umeshatumika, au umefutwa na mmiliki!");
            return;
        }

        const docId = snap.docs[0].id;
        const d = snap.docs[0].data();

        // Kuzuia mtumiaji kulipia mkataba aliojitengenezea mwenyewe
        if (d.userId === currentUser.uid) {
            if (preview) preview.style.display = 'none';
            alert(" Huwezi kulipia mkataba ulioutengeneza wewe mwenyewe!");
            return;
        }

        // Kuhifadhi data ya mkataba huu kwa muda kwenye global memory ya miamala
        currentOpenProduct = { id: docId, isSokoPay: true, ...d };

        // Chora muonekano wa preview maridadi ya mkataba
        if (preview) {
            preview.innerHTML = `
                <div style="display:flex; gap:12px; align-items:center; text-align:left;">
                    <img src="${skhEscape(getOptimizedImageUrl(d.image))}" style="width:60px; height:65px; border-radius:12px; object-fit:cover; border:1px solid #E2E8F0;" onerror="this.src='https://ui-avatars.com/api/?name=SokoPay&background=cbd5e1&color=0f172a'">
                    <div>
                        <span style="font-size: 8px; background: #FFFBEB; color: #B45309; padding: 2px 8px; border-radius: 10px; font-weight: bold; text-transform: uppercase;">Mkataba wa ${skhEscape(d.contractType.toUpperCase())}</span>
                        <b style="font-size:13px; display:block; color:#0F172A; margin-top:4px;">${skhEscape(d.title)}</b>
                        <span style="display:block; color:var(--terracotta); font-weight:900; margin-top:2px;">TSh ${d.price.toLocaleString()}</span>
                        <small style="color:gray; font-size:10px; display:block; margin-top:2px;">Umetengenezwa na: <b>${skhEscape(d.ownerName)}</b></small>
                    </div>
                </div>
            `;
        }

        // Badilisha vitufe vya muamala
        if (btnVerify) btnVerify.style.display = 'none';
        if (btnProceed) btnProceed.style.display = 'block';

    } catch (err) {
        if (preview) preview.style.display = 'none';
        alert(" Hitilafu ya mtandao wakati wa uhakiki: " + err.message);
    }
};

// 2. KULIPIA MKATABA (INTELLIGENT HYBRID CHECKOUT - WALLET VS GATEWAY)
window.proceedToPaySokoPay = async function() {
    if (!currentOpenProduct) return;

    const price = parseFloat(currentOpenProduct.price || 0);
    const walletBalance = parseFloat(currentUserData?.walletBalance || 0);

    // Kagua kama Salio la Wallet linatosha kufanya malipo ya papo hapo (Instant Escrow)
    if (walletBalance >= price) {
        if (confirm(` SALIO LA WALLET LINATOSHA!\n\nJe, unathibitisha kufanya malipo ya papo hapo ya TSh ${price.toLocaleString()} kutoka kwenye salio lako la Wallet (TSh ${walletBalance.toLocaleString()}) ili kufunga fedha kwenye Escrow?`)) {
            await window.executeSokoPayWalletPayment(currentOpenProduct.id, price);
        }
    } else {
        // Ikiwa salio halitoshi, mpeleke kwenye dirisha la kawaida la checkout la AzamPay
        const confirmationMsg = ` Salio la wallet yako halitoshi (Salio la sasa: TSh ${walletBalance.toLocaleString()}).\n\nSokoPay inakuelekeza kwenye dirisha la malipo ya mitandao ya simu (M-Pesa, Tigo, Airtel) au benki ili kukamilisha Escrow ya TSh ${price.toLocaleString()}.`;
        alert(confirmationMsg);
        
        activeCheckoutAmount = price;
        window.openCheckout('direct'); // Hii inaita function ya kawaida ya checkout iliyopo kwenye App yako
    }
};

// 3. KUTEKELEZA MALIPO YA INSTANT KWA NJIA YA SOKOPAY WALLET
window.executeSokoPayWalletPayment = async function(linkDocId, price) {
    const btnProceed = document.getElementById('btnProceedPaySp');
    const originalText = btnProceed ? btnProceed.innerHTML : "Lipia";
    
    if (btnProceed) {
        btnProceed.innerHTML = " Inakata Salio na Kufunga Escrow...";
        btnProceed.disabled = true;
    }

    try {
        const buyerDocRef = doc(db, "users", currentUserData.docId);
        const linkDocRef = doc(db, "sokopay_links", linkDocId);

        // A. Kata kiasi cha mkataba kwenye salio la Wallet ya mnunuzi
        // [PHASE 5.2b] kituo kimoja — skhWalletAdjust (legacy 1:1 geti likiwa off; server+ledger ikiwa on)
        await window.skhWalletAdjust(buyerDocRef, -price, { type: 'purchase', ledgerKey: 'splink_buy_' + linkDocId, note: 'Ununuzi wa mkataba wa SokoPay kutoka wallet' });

        // B. Sasisha mkataba kwenye sokopay_links uwe 'held' (Escrow Active)
        await updateDoc(linkDocRef, {
            status: "held",
            buyerId: currentUser.uid,
            buyerName: currentUser.displayName || "Mwanachama",
            paidAt: new Date().toISOString(),
            paymentType: "Wallet Payout"
        });

        // C. Sajili muamala kwenye orders collection kwa ajili ya mnyororo mkuu wa kufuatilia (Tracking)
        await addDoc(collection(db, "orders"), {
            buyerId: currentUser.uid,
            buyerName: currentUser.displayName || "Mwanachama",
            sellerId: currentOpenProduct.userId,
            sellerName: currentOpenProduct.ownerName,
            itemId: linkDocId,
            itemTitle: currentOpenProduct.title,
            amount: price,
            status: "held", // Pesa ipo locked salama
            paymentRef: currentOpenProduct.code,
            paymentType: "Wallet Payout",
            date: new Date().toISOString()
        });

        // D. Mtumie muuzaji/mtoa huduma taarifa (Notification) kwamba mkataba umefungwa na pesa ipo salama
        await addDoc(collection(db, "notifications"), {
            userId: currentOpenProduct.userId,
            title: " SokoPay: Malipo ya Escrow Yamefungwa!",
            body: `Mteja ameshalipia mkataba wa "${currentOpenProduct.title}" (TSh ${price.toLocaleString()}) kwa kutumia Wallet. Pesa ipo locked kwenye Escrow ya SokoPay, unaweza kuanza kazi/kusafirisha sasa.`,
            createdAt: new Date().toISOString(),
            read: false
        });

        alert(` USALAMA IMETIMIA!\n\nTSh ${price.toLocaleString()} imekatwa kwenye Wallet yako na kufungwa salama kwenye Escrow ya SokoPay.\n\nMuuzaji ameshapewa taarifa kuanza kutoa huduma au kusafirisha mzigo.`);
        
        // Weka upya muonekano
        document.getElementById('spCodeInputPay').value = '';
        document.getElementById('spItemPreview').style.display = 'none';
        if (btnProceedPaySp) btnProceedPaySp.style.display = 'none';
        document.getElementById('btnVerifySp').style.display = 'block';

        window.toggleSokoPayTab('track');
        window.syncSokoPayRealtimeData(); // Refreshes balances and charts live

    } catch (err) {
        alert(" Imeshindwa kukamilisha malipo ya wallet: " + err.message);
    } finally {
        if (btnProceed) {
            btnProceed.innerHTML = originalText;
            btnProceed.disabled = false;
        }
    }
};


