// 1. FUATILIA MKATABA KWA MSIMBO (TRACK TRANSACTION)
window.trackSokoPayTransaction = async function() {
    const code = document.getElementById('spCodeInputTrack').value.trim().toUpperCase();
    const resultBox = document.getElementById('spTrackResult');
    const actionsArea = document.getElementById('spTrackActions');
    
    if (!code || !resultBox) {
        alert(" Tafadhali ingiza msimbo wa mkataba!");
        return;
    }

    resultBox.innerHTML = '<p style="text-align:center; color:gray; font-size:11px; padding:10px;"> Inatafuta mkataba kwenye daftari la miamala...</p>';
    resultBox.style.display = 'block';
    if (actionsArea) actionsArea.style.display = 'none';

    try {
        // Tafuta mkataba kwenye sokopay_links
        const q = query(collection(db, "sokopay_links"), where("code", "==", code));
        const snap = await getDocs(q);

        if (snap.empty) {
            resultBox.innerHTML = '<p style="text-align:center; color:#EF4444; font-size:11px; padding:10px; font-weight:bold;"> Msimbo huu haupatikani kwenye mfumo wetu!</p>';
            return;
        }

        const docId = snap.docs[0].id;
        const d = snap.docs[0].data();
        let statusText = '';
        let statusColor = 'orange';

        if (d.status === 'pending') {
            statusText = ' Kusubiri Malipo (Pending Payment)';
            statusColor = 'orange';
        } else if (d.status === 'held') {
            statusText = ' Ipo Kwenye Ulinzi (Held in Escrow)';
            statusColor = 'green';
            
            // Washa vitufe vya Action (Confirm / Dispute) ikiwa pesa ipo Escrow na mnunuzi ndiye anayeangalia
            if (actionsArea && currentUser && currentUser.uid === d.buyerId) {
                actionsArea.style.display = 'flex';
                
                // Unganisha kazi za vitufe hivyo na mifumo yao ya payout na dispute
                document.getElementById('btnSpConfirmReceived').onclick = function() {
                    window.confirmSokoPayLinkDirect(docId, d.userId, d.price, d.carrierShare);
                };
                document.getElementById('btnSpRaiseDispute').onclick = function() {
                    window.raiseSokoPayLinkDispute(docId);
                };
            }
        } else if (d.status === 'completed') {
            statusText = ' Imekamilika & Imetolewa (Released)';
            statusColor = '#00509d';
        } else if (d.status === 'disputed') {
            statusText = ' Mkataba una Mgogoro (Disputed)';
            statusColor = 'red';
        }

        resultBox.innerHTML = `
            <div style="background:white; border:1px solid #cbd5e1; padding:15px; border-radius:16px; font-size:12px; text-align:left;">
                <b style="font-size:14px; display:block; color:var(--primary-dark); margin-bottom:8px;">Mkataba: ${d.title}</b>
                <span style="display:block; margin-bottom:4px;">Aina ya Mkataba: <b>${d.contractType.toUpperCase()}</b></span>
                <span style="display:block; margin-bottom:4px;">Kiasi cha Escrow: <b style="color:var(--terracotta);">TSh ${d.price.toLocaleString()}</b></span>
                <span style="display:block; margin-bottom:4px;">Hali ya Muamala: <b style="color:${statusColor};">${statusText}</b></span>
                <span style="display:block; margin-bottom:4px;">Mmiliki wa Mkataba: <b>${skhEscape(d.ownerName)}</b></span>
                ${d.disputeReason ? `<p style="font-size:11px; background:#fff5f5; color:red; padding:8px; border-radius:8px; margin-top:10px; border:1px solid #fecaca;"><b>Sababu ya Mgogoro:</b> ${d.disputeReason}</p>` : ''}
            </div>`;

    } catch (err) {
        resultBox.innerHTML = `<p style="color:red; text-align:center; padding:10px;">Hitilafu ya mtandao: ${skhEscape(err.message)}</p>`;
    }
};

