// 1. Swichi ya menyu za miamala kwenye POS
window.switchPosActionType = function() {
    const action = document.getElementById('posActionType').value;
    const areas = {
        sale: 'posSaleArea',
        receive_payment: 'posReceivePaymentArea',
        return: 'posReturnArea',
        expense: 'posExpenseArea',
        supplier: 'posSupplierArea'
    };

    // Ficha na uonyeshe eneo husika
    Object.keys(areas).forEach(key => {
        const el = document.getElementById(areas[key]);
        if(el) el.style.display = (key === action || (key === 'sale' && action === 'debt')) ? 'block' : 'none';
    });

    // Swichi maalum ya Cash vs Debt details
    const cashDetail = document.getElementById('posCashPaymentDetail');
    const debtDetail = document.getElementById('posDebtPaymentDetail');
    
    if (action === 'sale') {
        if(cashDetail) cashDetail.style.display = 'block';
        if(debtDetail) debtDetail.style.display = 'none';
    } else if (action === 'debt') {
        if(cashDetail) cashDetail.style.display = 'none';
        if(debtDetail) debtDetail.style.display = 'block';
    }
};

// 2. Kutafuta wadaiwa (Debtors Search) live
window.searchDebtorsLive = async function() {
    const input = document.getElementById('posSearchDebtorInp');
    const results = document.getElementById('posDebtorSearchResults');
    if(!input || !results) return;

    const queryStr = input.value.trim().toLowerCase();
    if(queryStr.length < 1) { results.innerHTML = ''; results.style.display = 'none'; return; }

    const ownerUid = currentUserData?.shopOwnerUid || currentUser.uid;
    const q = query(collection(db, "shop_ledger"), where("shopOwnerId", "==", ownerUid), where("type", "==", "debt"), where("status", "==", "pending"));
    const snap = await getDocs(q);

    let html = '';
    snap.forEach(docSnap => {
        const d = docSnap.data();
        if(d.title.toLowerCase().includes(queryStr)) {
            html += `
                <div onclick="window.selectDebtorForPayment('${docSnap.id}', '${d.title.replace(/'/g, "\\'")}', ${d.amount})" style="padding:10px; border-bottom:1px solid #eee; cursor:pointer; background:white;">
                    <b> ${d.title}</b> (Inayodaiwa: TSh ${d.amount.toLocaleString()})
                </div>`;
        }
    });

    results.innerHTML = html || '<p style="padding:10px; font-size:11px; color:gray;">Mteja hajapatikana...</p>';
    results.style.display = 'block';
};

