// --- SOKOHAI COCKPIT: PASSENGER BOARDING BY TICKET OTP ---
window.boardPassengerByOtp = async function() {
    const otp = document.getElementById('paxTicketOtpInp').value.trim();
    if(!otp) return alert(" Ingiza Ticket OTP kwanza!");

    try {
        const q = query(collection(db, "ride_requests"), where("reqCategory", "==", "Passengers"), where("transferCode", "==", otp), where("driverId", "==", currentUser.uid));
        const snap = await getDocs(q);

        if(snap.empty) {
            alert(" Ticket OTP si sahihi au safari hii haijapangiwa kwako!");
            return;
        }

        const rideId = snap.docs[0].id;
        await updateDoc(doc(db, "ride_requests", rideId), {
            status: "in_transit"
        });

        alert(" Abiria amethibitishwa kupanda salama (Boarding Complete)! Safari imeanza .");
        document.getElementById('paxTicketOtpInp').value = '';
        window.renderDriverActiveTabContent();
    } catch(e) {
        alert("Hitilafu: " + e.message);
    }
};


window.triggerVehicleBreakdown = async function(rideId, cargoName) {
    if(!confirm(` EMERGENCY BREAKDOWN RECOVERY ENGINE:\n\nJe, chombo chako kimepata hitilafu au dharura njiani?\n\nMfumo utahifadhi mkataba na Escrow yote, lakini utarudisha safari ya "${cargoName}" sokoni ili dereva wa karibu aje kuendeleza safari ya mzigo salama.`)) return;

    try {
        const rideRef = doc(db, "ride_requests", rideId);
        
        // Rudisha safari sokoni na weka alama ya uokoaji
        await updateDoc(rideRef, {
            status: "searching", // Mzigo unarudi kutafuta dereva mpya
            oldDriverId: currentUser.uid,
            oldDriverName: currentUser.displayName,
            driverId: null,      // Ondoa dereva aliyepata ajali/hitilafu
            driverName: null,
            driverPhone: null,
            driverVehicleReg: null,
            isRecoveryActive: true,
            breakdownAt: new Date().toISOString()
        });

        // Vuta taarifa za safari ili kujua mnunuzi
        const docSnap = await getDoc(rideRef);
        if(docSnap.exists()) {
            const rd = docSnap.data();
            
            // 1. Mtumie Mnunuzi arifa ya dharura
            await addDoc(collection(db, "notifications"), {
                userId: rd.customerId,
                title: " Uokoaji wa Safari Umeanzishwa (Recovery Active)",
                body: `Chombo cha dereva kimepata hitilafu njiani. Safari ya "${cargoName}" imerudishwa sokoni automatically ili dereva wa karibu aje kuendeleza safari salama bila kuvunja Escrow.`,
                createdAt: new Date().toISOString(),
                read: false
            });

            // 2. Mtumie na Muuzaji (Dukani) arifa ili ajue kinachoendelea
            if (rd.parentRideId) {
                const qOrder = query(collection(db, "orders"), where("buyerId", "==", rd.customerId), where("itemId", "==", rd.parentRideId));
                const orderSnap = await getDocs(qOrder);
                if (!orderSnap.empty) {
                    await addDoc(collection(db, "notifications"), {
                        userId: orderSnap.docs[0].data().sellerId,
                        title: " Ujumbe: Hitilafu ya Usafiri!",
                        body: `Mzigo wa mteja wako uliopo njiani umepata hitilafu ya chombo. Usijali, mfumo unatafuta gari lingine mtaani sasa hivi.`,
                        createdAt: new Date().toISOString(),
                        read: false
                    });
                }
            }
        }

        alert(" Mfumo wa Uokoaji umewashwa! Mkataba wako upo salama na safari imerudishwa sokoni kwa uokoaji wa haraka.");
        window.renderDriverActiveTabContent();
    } catch(e) {
        alert(" Kosa kuanzisha uokoaji: " + e.message);
    }
};

// --- WORKSPACE YA MIZIGO NA DISPATCH KWA MUUZAJI (SELLER DISPATCH) ---
window.renderSellerLogisticsTab = async function() {
    const ws = document.getElementById('dashWorkspace');
    if(!ws || !currentUser) return;

    ws.innerHTML = `
        <div style="text-align:left; animation: fadeIn 0.3s ease;">
            <h3 style="color:var(--primary-dark); margin-top:0; text-transform:uppercase;"> MIZIGO, DISPATCH & VERIFY PICKUP</h3>
            <p style="color:gray; font-size:12px; margin-bottom:20px;">Hapa ndipo unapomthibitisha dereva anapokuja kuchukua mzigo dukani kwako kwa kutumia Token A (PK) [1].</p>

            <!-- INPUT YA KULIPIA/KUHAKIKI TOKEN A (SELLER DISPATCH CONTROLS) -->
            <div style="background:#fffbeb; border:1.5px dashed var(--gold); padding:20px; border-radius:16px; margin-bottom:25px;">
                <b style="color:var(--primary-dark); font-size:13px; display:block; margin-bottom:10px; text-transform:uppercase;"> HAKIKI TOKENS ZA MAREJESHO / DISPATCH</b>
                <p style="font-size:11px; color:#475569; margin-bottom:15px;">Weka Token A (Pickup Token - PK-XXXX) uliyopewa na dereva kuthibitisha kuwa chombo chake kinalingana na oda:</p>
                <div style="display:flex; gap:10px; margin-bottom:15px;">
                    <input type="text" id="sellerDispatchTokenInp" placeholder="Ingiza Token A (Mfano: PK-1234)..." style="flex:2; padding:15px; border-radius:12px; border:1px solid #cbd5e1; outline:none; text-align:center; font-weight:900; font-size:18px; text-transform:uppercase;">
                    <button onclick="window.verifySellerDispatchToken()" id="btnVerifySellerDispatch" style="flex:1; padding:15px; background:var(--primary-blue); color:white; border:none; border-radius:12px; font-weight:900; cursor:pointer;">HAKIKI </button>
                </div>
                <div id="sellerDispatchResult" style="display:none; background:#f0fdf4; border:1px solid #bbf7d0; padding:15px; border-radius:14px; margin-bottom:15px; text-align:left;"></div>
                <button onclick="window.confirmSellerDispatch()" id="btnConfirmSellerDispatch" style="display:none; width:100%; padding:16px; background:var(--green); color:white; border:none; border-radius:14px; font-weight:900; font-size:14px; cursor:pointer; text-transform:uppercase;"> THIBITISHA KUKABIDHI MZIGO KWA DEREVA</button>
            </div>

            <!-- LIST YA ODA ZINAZOSUBIRI KUCHUKULIWA -->
            <b style="font-size:13px; color:var(--primary-dark); display:block; margin-bottom:12px; text-transform:uppercase;"> ODA ZINAZOSUBIRI KUCHUKULIWA (PENDING DISPATCH)</b>
            <div id="sellerPendingDispatchList">Inapakia mizigo...</div>
        </div>
    `;

    // Load pending dispatch items from Firestore
    const shopOwnerId = currentUserData?.shopOwnerUid || currentUser.uid;
    const qPending = query(
        collection(db, "ride_requests"),
        where("status", "in", ["accepted", "awaiting_pickup"]),
        limit(30)
    );

    // Filter and render
    window.skhOnSnapshot('agent-pending', qPending, (snap) => {
        const listDiv = document.getElementById('sellerPendingDispatchList');
        if(!listDiv) return;

        let html = '';
        let count = 0;

        snap.forEach(docSnap => {
            const rd = docSnap.data();
            count++;
            const cargoImg = rd.cargoImage || "https://ui-avatars.com/api/?name=Mzigo&background=cccccc&color=fff";
            html += `
                <div style="background:white; border:1px solid #cbd5e1; padding:15px; border-radius:16px; margin-bottom:10px; display:flex; justify-content:space-between; align-items:center;">
                    <div style="display:flex; gap:12px; align-items:center;">
                        <img src="${cargoImg}" style="width:45px; height:45px; border-radius:8px; object-fit:cover; border:1px solid #eee;">
                        <div>
                            <b style="font-size:14px; color:#0f172a; display:block;"> ${rd.cargoName}</b>
                            <span style="font-size:11px; color:gray; display:block;">Mteja: ${skhEscape(rd.customerName)} | Njia: ${rd.fromLocation} ➔ ${rd.toLocation}</span>
                            <span style="font-size:11px; color:orange; font-weight:bold; display:block; margin-top:2px;">Dereva: ${skhEscape(rd.driverName || 'N/A')} (Chombo: ${rd.vehicleType})</span>
                        </div>
                    </div>
                    <div style="text-align:right;">
                        <span style="font-size:10px; background:#fffbeb; color:#d97706; padding:4px 8px; border-radius:8px; font-weight:bold; display:block; margin-bottom:5px;">${rd.status.toUpperCase()}</span>
                        <b style="font-size:12px; color:var(--primary-blue);">Token A: ${rd.pickupToken}</b>
                    </div>
                </div>
            `;
        });

        listDiv.innerHTML = count === 0 
            ? `<p style="text-align:center; color:gray; font-size:12px; padding:20px; background:white; border-radius:12px; border:1px solid #e2e8f0;">Hakuna mizigo inayokusubiri uikabidhi kwa sasa.</p>` 
            : html;
    });
};

window.verifySellerDispatchToken = async function() {
    const token = document.getElementById('sellerDispatchTokenInp').value.trim().toUpperCase();
    if(!token) return alert(" Tafadhali weka Token A (PK) kwanza!");

    const resultBox = document.getElementById('sellerDispatchResult');
    const btnVerify = document.getElementById('btnVerifySellerDispatch');
    const btnConfirm = document.getElementById('btnConfirmSellerDispatch');

    resultBox.style.display = 'none';
    btnVerify.innerHTML = " Inatafuta...";
    btnVerify.disabled = true;

    try {
        const q = query(collection(db, "ride_requests"), where("pickupToken", "==", token), where("status", "in", ["accepted", "awaiting_pickup"]));
        const snap = await getDocs(q);

        if(!snap.empty) {
            const rd = snap.docs[0].data();
            sessionStorage.setItem('active_seller_verified_ride_id', snap.docs[0].id);

            resultBox.innerHTML = `
                <div style="font-size:13px; color:#1e293b; line-height:1.5; text-align:left;">
                    <b style="color:var(--green); display:block; margin-bottom:8px; font-size:14px; text-transform:uppercase;"> Token A Imethibitishwa!</b>
                    <span>Mzigo: <b>${rd.cargoName}</b></span><br>
                    <span>Mteja: <b>${skhEscape(rd.customerName)}</b></span><br>
                    <span>Dereva: <b style="color:var(--primary-blue);">${skhEscape(rd.driverName)}</b> (Chombo: ${rd.vehicleType})</span>
                </div>
            `;
            resultBox.style.display = 'block';
            btnVerify.style.display = 'none';
            btnConfirm.style.display = 'block';
        } else {
            alert(" Token hii si sahihi au mzigo tayari umeshatolewa!");
        }
    } catch (e) {
        alert("Hitilafu: " + e.message);
    } finally {
        btnVerify.innerHTML = "HAKIKI ";
        btnVerify.disabled = false;
    }
};

window.confirmSellerDispatch = async function() {
    const rideId = sessionStorage.getItem('active_seller_verified_ride_id');
    if(!rideId) return;

    const btnConfirm = document.getElementById('btnConfirmSellerDispatch');
    btnConfirm.innerHTML = " Inasave...";
    btnConfirm.disabled = true;

    try {
        const rideRef = doc(db, "ride_requests", rideId);
        await updateDoc(rideRef, {
            status: "in_transit",
            pickupToken: "USED",
            dispatchedAt: new Date().toISOString()
        });

        alert(" MZIGO UMEKABIDHIWA KWA DEREVA SALAMA!\n\nDereva amesharuhusiwa kuanza safari (Status: In Transit).");
        
        // Funga / weka upya fomu
        document.getElementById('sellerDispatchTokenInp').value = '';
        document.getElementById('sellerDispatchResult').style.display = 'none';
        document.getElementById('btnVerifySellerDispatch').style.display = 'block';
        btnConfirm.style.display = 'none';
        sessionStorage.removeItem('active_seller_verified_ride_id');
        
        window.renderSellerLogisticsTab();
    } catch (e) {
        alert("Hitilafu: " + e.message);
    } finally {
        btnConfirm.innerHTML = " THIBITISHA KUKABIDHI MZIGO KWA DEREVA";
        btnConfirm.disabled = false;
    }
};

