window.setupDriverActiveJobsQuery = function() {
    const container = document.getElementById('driverActiveJobsArea');
    if(!container) return;

    const qRides = query(collection(db, "ride_requests"), where("driverId", "==", currentUser.uid));

    window.skhOnSnapshot('driver-rides', qRides, (snapshot) => {
        let html = '';
        let count = 0;

        snapshot.forEach(docSnap => {
            const rd = docSnap.data();
            const rid = docSnap.id;

            if (rd.status !== "completed" && rd.status !== "cancelled") {
                count++;
                const cargoImg = rd.cargoImage || "https://ui-avatars.com/api/?name=Mzigo&background=cccccc&color=fff";
                const pToken = rd.pickupToken || "Bado";
                const cPhone = rd.customerPhone || "Haikujazwa";

                html += `
                    <div style="background:#f8fafc; border:1px solid #cbd5e1; border-radius:18px; padding:15px; margin-bottom:12px; border-left:6px solid var(--primary-blue); text-align:left;">
                        <div style="display:flex; justify-content:space-between; align-items:center; margin-bottom:8px;">
                            <span style="font-size:10px; background:#e0f2fe; color:#03509d; padding:2px 8px; border-radius:10px; font-weight:bold; text-transform:uppercase;">${rd.status.toUpperCase()}</span>
                            <small style="color:gray;">${new Date(rd.createdAt).toLocaleDateString()}</small>
                        </div>
                        <div style="display:flex; gap:10px; align-items:center;">
                            <img src="${cargoImg}" style="width:40px; height:40px; border-radius:8px; object-fit:cover; border:1px solid #eee;">
                            <div>
                                <b style="font-size:14px; color:#0f172a; display:block;">${rd.cargoName}</b>
                                <small style="color:gray;">Mteja: ${skhEscape(rd.customerName)} | Simu: ${cPhone}</small>
                            </div>
                        </div>
                        <div style="background:white; padding:8px; border-radius:8px; margin-top:8px; font-size:12px; border:1px solid #eee;">
                             Kutoka: <b>${rd.fromLocation}</b> ➔ Kwenda: <b>${rd.toLocation}</b>
                        </div>
                        <div style="background:#fffbeb; padding:10px; border-radius:10px; margin-top:10px; border:1.5px dashed #d97706; font-size:12px;">
                            <b style="color:#d97706; display:block; margin-bottom:4px;"> Token A (Pickup Verification): ${pToken}</b>
                            ${rd.status === 'in_transit' ? 'Mzigo upo njiani! Mwombe mteja Token C unapomkabidhi.' : `Mpe muuzaji Token ya <b>${pToken}</b> pale duka la <b>Mizigo & Dispatch</b> kuthibitisha utoaji.`}
                        </div>
                        <button onclick="window.triggerVehicleBreakdown('${rid}', '${rd.cargoName.replace(/'/g, "\\'")}')" style="width:100%; padding:10px; background:#fee2e2; color:#ef4444; border:none; border-radius:8px; font-weight:bold; cursor:pointer; font-size:11px; margin-top:10px;"> CHOMBO KIMEHARIBIKA (BREAKDOWN)</button>
                    </div>`;
            }
        });

        container.innerHTML = count === 0 
            ? `<p style="text-align:center; color:gray; font-size:12px; padding:20px;">Huna safari inayofanya kazi hivi sasa.</p>` 
            : html;
    });
};


window.loadMarketplaceRequests = function(filterType) {
    const listDiv = document.getElementById('liveBookingsList');
    if (!listDiv) return;

    const driverVehicleType = currentUserData?.vehicleType || "Bodaboda";

    const qBookings = query(
        collection(db, "ride_requests"), 
        where("status", "in", ["searching", "pending_acceptance"]), 
        limit(30)
    );

    window.skhOnSnapshot('driver-bookings', qBookings, (snap) => {
        let html = '';
        let count = 0;

        snap.forEach(docSnap => {
            const rd = docSnap.data();
            const rid = docSnap.id;

            // Chujio la aina ya kazi
            let matchesFilter = true;
            if (filterType !== 'all_types' && rd.reqCategory !== filterType) {
                matchesFilter = false;
            }

            if (matchesFilter && rd.vehicleType === driverVehicleType) {
                count++;
                const cargoImg = rd.cargoImage || "https://ui-avatars.com/api/?name=Usafiri&background=cccccc&color=fff";
                html += `
                    <div style="background:white; border:1px solid #cbd5e1; border-radius:14px; padding:15px; text-align:left; border-left:6px solid var(--gold);">
                        <div style="display:flex; justify-content:space-between; align-items:center; margin-bottom:8px;">
                            <span style="font-size:10px; background:#fffbeb; color:#d97706; padding:2px 8px; border-radius:10px; font-weight:bold; text-transform:uppercase;">MPYA</span>
                            <small style="color:gray;">Kategoria: ${rd.reqCategory}</small>
                        </div>
                        <div style="display:flex; gap:12px; align-items:center; margin-bottom:10px;">
                            <img src="${cargoImg}" style="width:45px; height:45px; border-radius:8px; object-fit:cover; border:1px solid #eee;">
                            <div>
                                <b style="font-size:14px; color:var(--primary-dark);">${rd.cargoName}</b>
                                <small style="display:block; color:gray;">Mteja: ${skhEscape(rd.customerName || 'Mteja')}</small>
                            </div>
                        </div>
                        <div style="background:#f8fafc; padding:10px; border-radius:8px; font-size:12px; margin-bottom:12px;">
                             Kutoka: <b>${rd.fromLocation}</b> ➔ Kwenda: <b>${rd.toLocation}</b>
                        </div>
                        <button onclick="window.acceptTransportMission('${rid}')" style="width:100%; padding:12px; background:var(--green); color:white; border:none; border-radius:10px; font-weight:bold; font-size:13px; cursor:pointer;">KUBALI KAZI HII ➔</button>
                    </div>`;
            }
        });

        listDiv.innerHTML = count === 0 
            ? `<p style="text-align:center; color:gray; font-size:11px; padding:20px;">Bado hakuna kazi inayopatikana kulingana na kigezo hiki kwa sasa.</p>` 
            : html;
    });
};

window.filterMarketplace = function(type, btnElement) {
    document.querySelectorAll('.bookings-tab').forEach(b => b.classList.remove('active'));
    if(btnElement) btnElement.classList.add('active');
    window.loadMarketplaceRequests(type);
};

window.verifyTokenCenterDL = async function() {
    const code = document.getElementById('tokenCenterInputDL').value.trim().toUpperCase();
    if(!code) return alert(" Tafadhali ingiza Token C kuthibitisha uwasilishaji!");

    try {
        const q = query(collection(db, "ride_requests"), where("transferCode", "==", code), where("driverId", "==", currentUser.uid));
        const snap = await getDocs(q);

        if(snap.empty) {
            alert(" Token C uliyoweka si sahihi! Hakiki vizuri na mpokeaji wa mzigo.");
            return;
        }

        const docId = snap.docs[0].id;
        const rd = snap.docs[0].data();
        const price = rd.cargoPrice || rd.price || 40000;

        await updateDoc(doc(db, "ride_requests", docId), { status: "completed" });
        // [PHASE 5.2b] kituo kimoja — skhWalletAdjust (legacy 1:1 geti likiwa off; server+ledger ikiwa on)
        await window.skhWalletAdjust(doc(db, "users", currentUser.uid), price, { type: 'payout', ledgerKey: 'cargodl_' + docId, note: 'Tofauti ya bei ya mzigo (Token Center)' });

        alert(` SAFARI IMEKAMILIKA!\n\nTofauti ya TSh ${price.toLocaleString()} imeingizwa kwenye wallet yako salama.`);
        document.getElementById('tokenCenterInputDL').value = '';
        window.switchDashTab('overview');
    } catch(e) {
        alert("Hitilafu: " + e.message);
    }
};





