//  ROLE-BASED DASHBOARD ROUTING ENGINE
// ==========================================
window.renderRoleBasedDashboard = function() {
    const role = currentUserData?.shopRole || 'owner';
    const sidebar = document.querySelector('.ct-sidebar');

    if(role === 'Cashier') {
        // Mhudumu anaona POS tu
        alert(" Cashier Privileges: Dashbodi yako imefungwa kwenye Mauzo/POS tu.");
        window.switchDashTab('overview');
        // Ficha menu zingine kwenye sidebar
        const linksToHide = ['_product_analytics', '_expenses', '_staff', '_settings'];
        linksToHide.forEach(id => {
            const el = document.getElementById('btnTab' + id);
            if(el) el.style.display = 'none';
        });
    } else if(role === 'Storekeeper') {
        // Shika stoo anaona stoo tu
        alert(" Storekeeper Privileges: Mamlaka yako yameelekezwa kwenye Stock & Inventory tu.");
        window.switchDashTab('inventory');
        const linksToHide = ['_product_analytics', '_expenses', '_staff', '_settings', '_overview'];
        linksToHide.forEach(id => {
            const el = document.getElementById('btnTab' + id);
            if(el) el.style.display = 'none';
        });
    } else {
        // Owner anaona kila kitu kiofisi
        document.querySelectorAll('.ct-sidebar-menu-btn').forEach(b => b.style.display = 'block');
    }
};

// Function ya kuthibitisha kupokea huduma/mkataba na kutoa malipo kwa usalama
window.confirmSokoPayLinkDirect = async function(docId, sellerId, totalAmount, carrierShare = 0) {
    if(!confirm(`Je, unathibitisha kuwa mkataba huu umekamilika vizuri?\n\nPesa ya mkataba itatumwa kwa wahusika sasa hivi.`)) return;

    try {
        const linkRef = doc(db, "sokopay_links", docId);
        
        // 1. Badili hali ya mkataba kuwa completed
        await updateDoc(linkRef, { status: "completed" });

        // 2. Toa pesa kwa muuzaji (itakayobaki baada ya kutoa carrier share na platform fee)
        const platformFee = totalAmount * 0.05; // 5% Platform Fee
        const sellerEarned = totalAmount - (platformFee + carrierShare);

        const sellerQuery = await getDocs(query(collection(db, "users"), where("uid", "==", sellerId)));
        if (!sellerQuery.empty) {
            const sellerDocId = sellerQuery.docs[0].id;
            // [PHASE 5.2b] kituo kimoja — skhWalletAdjust (legacy 1:1 geti likiwa off; server+ledger ikiwa on)
            await window.skhWalletAdjust(doc(db, "users", sellerDocId), sellerEarned, { type: 'escrow_release', ledgerKey: 'spman_link_' + linkRef.id, note: 'Kukamilisha mkataba wa SokoPay kwa mkono' });

            // Mtumie muuzaji taarifa
            await addDoc(collection(db, "notifications"), {
                userId: sellerId,
                title: " SokoPay: Mkataba Umekamilika!",
                body: `Mteja amethibitisha kukamilika kwa mkataba wako. TSh ${sellerEarned.toLocaleString()} imewekwa kwenye wallet yako.`,
                createdAt: new Date().toISOString(),
                read: false
            });
        }

        // 3. Rekodi makusanyo ya platform revenue
        await addDoc(collection(db, "adminRevenue"), {
            type: "sokopay_commission",
            amount: platformFee,
            date: new Date().toISOString()
        });

        alert(` Hongera! Mkataba umekamilishwa salama na pesa imetumwa kwa muuzaji.`);
        window.trackSokoPayTransaction(); // Refresh taarifa
    } catch(err) {
        alert(" Imeshindwa kukamilisha: " + err.message);
    }
};

// Function ya kufungua mgogoro (Dispute) kwa ajili ya SokoPay links
window.raiseSokoPayLinkDispute = async function(docId) {
    const reason = prompt("Andika sababu ya kufungua mgogoro huu kwa ufupi (Ushahidi):");
    if(!reason) return alert(" Lazima uandike sababu ili kufungua mgogoro.");

    try {
        const linkRef = doc(db, "sokopay_links", docId);
        await updateDoc(linkRef, {
            status: "disputed",
            disputeReason: reason,
            disputedAt: new Date().toISOString()
        });

        alert(" Mgogoro umefunguliwa na akaunti ya SokoPay imezuiwa! Admin atapitia malalamiko yako sasa hivi.");
        window.trackSokoPayTransaction();
    } catch(err) {
        alert("Hitilafu: " + err.message);
    }
};


