// 1. SASISHA UTARATIBU WA TOGGLE TAB ILI UIHUSISHE TAB MPYA
const originalToggleSokoPayTab = window.toggleSokoPayTab;

window.toggleSokoPayTab = function(tab) {
    // Orodha kamili ya IDs za maeneo ya SokoPay (Including Logistics Area, Lipa, Companies, Governance)
    const areas = [
        'spOverviewArea', 'spCreateArea', 'spPayArea', 'spTrackArea', 
        'spSettingsArea', 'spDisputesArea', 'spProductsArea', 'spServicesArea', 'spJobsArea', 'spLogisticsArea',
        'spLipaArea', 'spCompaniesArea', 'spGovernanceArea', 'spEventsArea' // [PHASE 5.2-UX] Events ilikuwa haionyeshwi (tab ya Events = skrini tupu)
    ];
    
    // Links za sidebar ya kushoto
    const tabButtons = document.querySelectorAll('#sokopayLeftSidebar .sp-sidebar-link');

    // Ficha zote na uonyeshe tab inayotakiwa tu
    areas.forEach(id => {
        const el = document.getElementById(id);
        if (el) {
            el.style.display = (id === 'sp' + tab.charAt(0).toUpperCase() + tab.slice(1) + 'Area') ? 'block' : 'none';
        }
    });

    // Weka alama ya active kwenye sidebar link husika
    tabButtons.forEach(btn => {
        const onclickAttr = btn.getAttribute('onclick') || '';
        if (onclickAttr.includes(`'${tab}'`)) {
            btn.classList.add('active');
            btn.style.background = '#00509d';
            btn.style.color = 'white';
        } else {
            btn.classList.remove('active');
            btn.style.background = 'transparent';
            btn.style.color = 'rgba(255, 255, 255, 0.65)';
        }
    });

    // Ikiwa amebofya bidhaa, huduma, ajira au logistics, amsha sub-tab yake ya kwanza
    if (tab === 'products') {
        window.switchProductSubTab('active');
        if (window.skhSpLive) window.skhSpLive.products(); // [PHASE 5.2-UX] data halisi badala ya demo
    } else if (tab === 'services') {
        window.switchServiceSubTab('contracts');
        if (window.skhSpLive) window.skhSpLive.services(); // [PHASE 5.2-UX]
    } else if (tab === 'jobs') {
        window.switchJobSubTab('contracts');
        if (window.skhSpLive) window.skhSpLive.jobs(); // [PHASE 5.2-UX]
    } else if (tab === 'logistics') {
        window.switchLogisticsSubTab('shipments');
        if (window.skhSpLive) window.skhSpLive.logistics(); // [PHASE 5.2-UX]
    } else if (tab === 'overview') {
        if (typeof window.syncSokoPayRealtimeData === 'function') {
            window.syncSokoPayRealtimeData();
        }
    }
};

// 2. KUBADILISHA VISANDUKU VYA NDANI YA SETTINGS KIOTOMATIKI (INTERNAL TOGGLE)
window.toggleSokoPayInternalSetupFields = function() {
    const type = document.getElementById('spSettingsPayType').value;
    const mobileDiv = document.getElementById('spSetMobileFields');
    const bankDiv = document.getElementById('spSetBankFields');
    const cardDiv = document.getElementById('spSetCardFields');

    if (mobileDiv) mobileDiv.style.display = (type === 'Mobile') ? 'block' : 'none';
    if (bankDiv) bankDiv.style.display = (type === 'Bank') ? 'block' : 'none';
    if (cardDiv) cardDiv.style.display = (type === 'Card') ? 'block' : 'none';
};

// 3. KUSOMA DATA ZOTE ZA SETTINGS KUTOKA FIREBASE (READ LIVE SETTINGS)
window.loadSokoPayInternalSettingsData = function() {
    if (!currentUserData) return;

    const pType = currentUserData.paymentType || '';
    const pAccount = currentUserData.paymentAccount || '';
    const pName = currentUserData.paymentName || '';
    
    const typeSelect = document.getElementById('spSettingsPayType');
    const btnSave = document.getElementById('btnSpSavePayment');
    const btnEdit = document.getElementById('btnSpEditPayment');

    if (typeSelect) typeSelect.value = pType;
    window.toggleSokoPayInternalSetupFields();

    // Kama tayari mteja alishasajili akaunti ya malipo, weka 'Locked' kwa usalama wake
    if (pType && pAccount) {
        window.lockSokoPayInternalSettings(true);
        if (btnSave) btnSave.style.display = 'none';
        if (btnEdit) btnEdit.style.display = 'block';

        // Jaza data kulingana na aina
        if (pType === 'Mobile') {
            document.getElementById('spSetMobileNumber').value = pAccount;
            document.getElementById('spSetMobileName').value = pName;
        } else if (pType === 'Bank') {
            document.getElementById('spSetBankNumber').value = pAccount;
            document.getElementById('spSetBankName').value = pName;
        } else if (pType === 'Card') {
            document.getElementById('spSetCardNumber').value = pAccount;
            document.getElementById('spSetCardName').value = pName;
        }
    } else {
        window.lockSokoPayInternalSettings(false);
        if (btnSave) btnSave.style.display = 'block';
        if (btnEdit) btnEdit.style.display = 'none';
    }

};

// 4. KUGANDISHA MIFUMO YA INPUTS KWA AJILI YA USALAMA (LOCK INPUTS)
window.lockSokoPayInternalSettings = function(isLocked) {
    const pm = document.getElementById('spSettingsArea');
    if (!pm) return;
    const inputs = pm.querySelectorAll('input, select');
    inputs.forEach(inp => {
        // Tuhakikishe namba za dharura za SOS hazigandishwi (mteja anaweza kuzibadili mda wowote)
        if (inp.id !== 'spTrustPhone1' && inp.id !== 'spTrustPhone2') {
            inp.disabled = isLocked;
            inp.style.opacity = isLocked ? '0.8' : '1';
        }
    });
};

// 5. KUFUNGUA LOCK ILI APATE RUHUSA YA KUHARIRI (ENABLE EDIT)
window.enableSokoPayInternalPaymentEdit = function() {
    window.lockSokoPayInternalSettings(false);
    document.getElementById('btnSpSavePayment').style.display = 'block';
    document.getElementById('btnSpEditPayment').style.display = 'none';
    alert("✏ Sasa unaweza kubadilisha taarifa zako za malipo. Ukimaliza bofya 'HIFADHI AKAUNTI'.");
};

// 6. KUHIFADHI AKAUNTI YA MALIPO YA NDANI YA SOKOPAY
window.saveSokoPayInternalPaymentInfo = async function() {
    if (!currentUser) return;

    const type = document.getElementById('spSettingsPayType').value;
    let accountNum = '';
    let accountName = '';

    if (type === 'Mobile') {
        accountNum = document.getElementById('spSetMobileNumber').value.trim();
        accountName = document.getElementById('spSetMobileName').value.trim();
    } else if (type === 'Bank') {
        accountNum = document.getElementById('spSetBankNumber').value.trim();
        accountName = document.getElementById('spSetBankName').value.trim();
    } else if (type === 'Card') {
        accountNum = document.getElementById('spSetCardNumber').value.trim();
        accountName = document.getElementById('spSetCardName').value.trim();
    }

    if (!type || !accountNum || !accountName) {
        alert(" Tafadhali jaza njia ya malipo na namba ya akaunti/laini vizuri!");
        return;
    }

    const btn = document.getElementById('btnSpSavePayment');
    btn.innerHTML = " Inahifadhi kiofisi...";
    btn.disabled = true;

    try {
        await updateDoc(doc(db, "users", currentUserData.docId), {
            paymentType: type,
            paymentAccount: accountNum,
            paymentName: accountName,
            paymentSetupComplete: true
        });

        alert(" Akaunti ya Malipo ya SokoPay imehifadhiwa salama kwenye wasifu wako!");
        window.loadSokoPayInternalSettingsData(); // Reload na kuji-lock automatically
    } catch (err) {
        alert(" Imeshindwa kuhifadhi akaunti: " + err.message);
    } finally {
        btn.innerHTML = " HIFADHI AKAUNTI YA MALIPO";
        btn.disabled = false;
    }
};

// 7. KUHIFADHI NAMBA ZA SALAMA ZA SOS (SAFETY CONTACTS)

// 8. KUSOMA NA KUCHORA MIGOGORO YA MTUMIAJI LIVE (LOAD DISPUTES LIST)
window.loadSokoPayInternalDisputes = async function() {
    const container = document.getElementById('spDisputesList');
    if (!container) return;

    container.innerHTML = '<p style="text-align:center; color:gray; font-size:11px;"> Inasoma kesi za migogoro...</p>';

    try {
        // Query migogoro ya mtumiaji kama Mnunuzi au Muuzaji
        const qBuyer = query(collection(db, "orders"), where("buyerId", "==", currentUser.uid), where("status", "==", "disputed"));
        const qSeller = query(collection(db, "orders"), where("sellerId", "==", currentUser.uid), where("status", "==", "disputed"));

        const [snapB, snapS] = await Promise.all([getDocs(qBuyer), getDocs(qSeller)]);
        
        let disputes = [];
        snapB.forEach(docSnap => disputes.push({ id: docSnap.id, role: "Mnunuzi", ...docSnap.data() }));
        snapS.forEach(docSnap => disputes.push({ id: docSnap.id, role: "Muuzaji", ...docSnap.data() }));

        if (disputes.length === 0) {
            container.innerHTML = `
                <div style="text-align:center; padding:30px; color:gray;">
                    <span style="font-size:36px;"></span>
                    <p style="font-size:11px; margin-top:5px;">Huna kesi yoyote ya mgogoro iliyo hai hivi sasa. Kila kitu kipo salama na shwari!</p>
                </div>`;
            return;
        }

        let html = '';
        disputes.forEach(d => {
            const amt = parseFloat(d.amount || d.price || 0);
            html += `
                <div style="background:#FFF5F5; border-left:5px solid #EF4444; padding:15px; border-radius:12px; border-top:1px solid #FECACA; border-right:1px solid #FECACA; border-bottom:1px solid #FECACA; text-align:left;">
                    <div style="display:flex; justify-content:space-between; align-items:center; margin-bottom:8px;">
                        <span style="font-size:9px; background:#FECACA; color:#EF4444; padding:2px 8px; border-radius:10px; font-weight:bold;">DISPUTED (Upo kama ${d.role})</span>
                        <small style="color:gray;">${new Date(d.date || d.createdAt).toLocaleDateString()}</small>
                    </div>
                    <b style="font-size:14px; color:#0F172A; display:block; margin-bottom:5px;"> Mkataba: ${skhEscape(d.itemTitle || d.title)}</b>
                    <span style="display:block; font-size:11px; color:#475569;">Kiasi kilichogandishwa: <b style="color:red;">TZS ${amt.toLocaleString()}</b></span>
                    <p style="background:white; padding:8px; border-radius:6px; font-size:11px; color:#ef4444; margin-top:8px; border:1px solid #fecaca; line-height:1.4;">
                        <b>Sababu ya Mgogoro:</b> ${d.disputeReason || 'N/A'}
                    </p>
                    <small style="display:block; color:gray; font-size:10px; margin-top:8px;">Uamuzi wa kesi hii utafanywa na msimamizi (Admin) baada ya kupitia ushahidi.</small>
                </div>`;
        });

        container.innerHTML = html;

    } catch (e) {
        container.innerHTML = '<p style="color:red; text-align:center; font-size:11px;">Hitilafu ya kupakia kesi.</p>';
    }
};

// 2. KUTEKELEZA USSD PUSH NA KUONGEZA SALIO WALLET
window.processSokoPayDeposit = async function() {
    const amountVal = parseFloat(document.getElementById('spDepositAmount').value) || 0;
    const provider = document.getElementById('spDepositProvider').value;
    let phone = document.getElementById('spDepositPhone').value.trim();

    if (amountVal < 100) {
        alert(" Kiwango cha chini cha kuweka ni TSh 100!");
        return;
    }

    if (!phone) {
        alert(" Tafadhali weka namba ya simu ya kulipia!");
        return;
    }

    const btn = document.getElementById('btnSubmitSpDeposit');
    const originalText = btn.innerHTML;
    btn.innerHTML = " INATUMA OMBI LA USSD PUSH...";
    btn.disabled = true;

    // Badilisha format ya namba kwenda 255...
    if (phone.startsWith('0')) {
        phone = '255' + phone.substring(1);
    }

    alert(` Ombi la muamala linatumwa kwenye simu yako (${phone}). Tafadhali weka PIN ya siri kuthibitisha malipo.`);

    try {
        // [PHASE 4.2b] AzamPay moja (simulation inatawaliwa na DEMO_MODE sasa)
        const dep = await window.skhAzamPayMno({ phone: phone, amount: amountVal, externalId: "DEPOSIT_" + Date.now(), provider: provider });
        let transactionId = dep.transactionId;

        if (dep.ok) {
            // A. Ongeza salio kwenye Wallet ya mtumiaji Firestore
            // [PHASE 5.2b] kituo kimoja — skhWalletAdjust (legacy 1:1 geti likiwa off; server+ledger ikiwa on)
            await window.skhWalletAdjust(doc(db, "users", currentUserData.docId), amountVal, { type: 'deposit', ledgerKey: 'deposit_' + transactionId, note: 'Deposit ya wallet (AzamPay)' });

            // B. Rekodi muamala kwenye vitabu vya duka la dharura (Ledger Inflow)
            await addDoc(collection(db, "shop_ledger"), {
                shopOwnerId: currentUser.uid,
                type: "income_offline",
                title: `Weka Pesa: Wallet Top-Up (${provider})`,
                amount: amountVal,
                profit: amountVal, // Kiasi kizima kinaingia kwenye mtaji wako
                date: new Date().toISOString()
            });

            // C. Mtumie mteja taarifa (Notification) kwamba salio lake limeongezeka
            await addDoc(collection(db, "notifications"), {
                userId: currentUser.uid,
                title: " SokoPay: Salio Limeongezeka!",
                body: `Umefanikiwa kuongeza kiasi cha TSh ${amountVal.toLocaleString()} kwenye wallet yako kupitia ${provider}. Salio lako jipya limeandikishwa [1].`,
                createdAt: new Date().toISOString(),
                read: false
            });

            alert(` HESABU IMESAWASISHWA!\n\nTSh ${amountVal.toLocaleString()} imewekwa kwenye Wallet yako ya SokoPay kwa njia ya ${provider}. Salio lako jipya limesasishwa live!`);
            
            // Funga fomu
            document.getElementById('spDepositAmount').value = '';
            document.getElementById('sokopayDepositModal').style.display = 'none';

            window.syncSokoPayRealtimeData(); // Refresh metrics na chati hapo hapo!

        } else {
            alert(" Kosa la usindikaji: Ombi la malipo limeshindikana. Kagua salio la simu yako.");
        }

    } catch (e) {
        alert("Hitilafu wakati wa kuweka pesa: " + e.message);
    } finally {
        btn.innerHTML = originalText;
        btn.disabled = false;
    }
};



