window.renderSokoHaiAccountMenu = function(){
    const modal=document.getElementById('sidebarMenuModal'); if(!modal) return;
    modal.className='overlay-menu skh-account-menu';
    modal.style.display='flex';
    modal.style.zIndex='100005';
    const name=currentUserData?.fullName || currentUser?.displayName || 'SokoHai User';
    const email=currentUser?.email || currentUserData?.phone || 'Account settings';
    const photo=currentUserData?.photoURL || currentUser?.photoURL || '';
    modal.innerHTML = `<div class="skh-menu-drawer"><div class="skh-menu-head"><div class="skh-menu-top"><b>☰ SOKOHAI</b><button class="skh-menu-close" onclick="window.closeModals()">✕</button></div><div class="skh-user-card"><img src="${skhEscape(photo)}" onerror="this.style.display='none'"><div><b>${skhEscape(name)}</b><small>${skhEscape(email)}</small></div></div></div><div class="skh-menu-scroll">${window.sokohaiAccountMenuItems.map(sec=>`<div class="skh-menu-section-title">${sec.section}</div>${sec.items.map(([key,ico,title,sub])=>`<button class="skh-menu-item ${key==='logout'?'skh-logout':''}" onclick="window.openSokoHaiAccountSetting('${key}')"><span class="ico">${ico}</span><span class="txt"><b>${title}</b><small>${sub}</small></span><span class="chev">›</span></button>`).join('')}`).join('')}<button class="skh-menu-item skh-logout" onclick="window.openSokoHaiAccountSetting('logout')"><span class="ico"></span><span class="txt"><b>Logout</b><small>Logout, logout all devices, switch account</small></span><span class="chev">›</span></button></div></div>`;
};

