window.calculatePrintingCost = function(){
    const val = id => document.getElementById(id)?.value;
    const jobType=val('prJobType') || 'photocopy';
    const pages=Math.max(1, parseInt(val('prPages')||'1'));
    const copies=Math.max(1, parseInt(val('prCopies')||'1'));
    const paperSize=val('prPaperSize') || 'A4';
    const sides=val('prSides') || 'single';
    const finishing=val('prFinishing') || 'none';
    const urgency=val('prUrgency') || 'normal';
    const delivery=val('prDelivery') || 'pickup';
    const deposit=parseFloat(val('prDeposit')||'0') || 0;
    let rate=window.printingRatesPro[jobType] || 100;
    if(paperSize==='A3') rate=Math.round(rate*1.8);
    const chargeUnits = (jobType==='binding' || jobType==='passport_photo') ? copies : pages*copies;
    const sheetsUsed = sides==='double' ? Math.ceil(pages/2)*copies : pages*copies;
    let base=rate*chargeUnits;
    let finishCost=0;
    if(finishing==='binding') finishCost += 1500*copies;
    if(finishing==='lamination') finishCost += 1000*pages*copies;
    let extra=0;
    if(urgency==='urgent') extra += Math.round((base+finishCost)*0.2);
    if(delivery==='delivery') extra += 2000;
    const total=base+finishCost+extra;
    const balance=Math.max(0,total-deposit);
    const set=(id,txt)=>{ const el=document.getElementById(id); if(el) el.innerText=txt; };
    set('prTotalCostDisplay', `TSh ${total.toLocaleString()}`); set('prUnitRate', `TSh ${rate.toLocaleString()}`); set('prSheetsUsed', sheetsUsed.toLocaleString()); set('prBaseSubtotal', `TSh ${base.toLocaleString()}`); set('prFinishCost', `TSh ${finishCost.toLocaleString()}`); set('prExtraCost', `TSh ${extra.toLocaleString()}`); set('prBalanceDisplay', `TSh ${balance.toLocaleString()}`);
    window.activePrintingCalc={ jobType,pages,copies,paperSize,sides,finishing,urgency,delivery,rate,sheetsUsed,base,finishCost,extra,total,balance,deposit };
    window.activePrintingTotalCost=total;
    return window.activePrintingCalc;
};

document.addEventListener('input', e => { if(e.target && ['prDeposit'].includes(e.target.id)) window.calculatePrintingCost(); });

async function uploadPrintingFileIfAny(){
    const file=document.getElementById('prFileInput')?.files?.[0]; if(!file) return null;
    // [PHASE 4.2] Uploader mmoja wa pamoja (folder: sokohai_printing_jobs)
    try{ const r=await window.skhUploadFromFile(file,{folder:'sokohai_printing_jobs'}); return (r && r.url) ? { url:r.url, name:file.name, type:file.type, size:file.size, provider:'cloudinary' } : { name:file.name, type:file.type, size:file.size, provider:'local_only' }; }catch(e){ return { name:file.name, type:file.type, size:file.size, provider:'upload_failed', error:e.message }; }
}

window.savePrintingJob = async function(){
    if(!currentUser) return alert('Ingia kwanza.');
    const custName=document.getElementById('prCustName')?.value?.trim();
    if(!custName) return alert(' Jaza jina la mteja/shule/ofisi.');
    const calc=window.calculatePrintingCost();
    const ownerUid=currentUserData?.shopOwnerUid || currentUser.uid;
    const btn=document.querySelector('.prt-btn-primary'); if(btn){ btn.disabled=true; btn.innerText='Saving...'; }
    try{
        const fileMeta=await uploadPrintingFileIfAny();
        const jobCode='PRT-'+Math.floor(1000+Math.random()*9000);
        const payload={ shopOwnerId:ownerUid, userId:currentUser.uid, jobCode, customerName:custName, customerPhone:document.getElementById('prCustPhone')?.value || '', notes:document.getElementById('prNotes')?.value || '', paymentStatus:document.getElementById('prPaymentStatus')?.value || 'paid', dueTime:document.getElementById('prDueTime')?.value || '', file:fileMeta, ...calc, status:'queued', createdAt:new Date().toISOString() };
        await addDoc(collection(db,'printing_jobs'), payload);
        await addDoc(collection(db,'shop_ledger'), { shopOwnerId:ownerUid, type: calc.balance>0 ? 'receivable' : 'income_offline', title:`Printing Job ${jobCode}: ${calc.jobType} - ${calc.pages} pages x ${calc.copies}`, amount:calc.total, paidAmount:calc.total-calc.balance, balance:calc.balance, profit:Math.round(calc.total*0.75), date:new Date().toISOString(), ref:jobCode });
        await window.reducePrintingPaperStock?.(ownerUid, calc.sheetsUsed);
        alert(` Kazi imehifadhiwa: ${jobCode}\nJumla: TSh ${calc.total.toLocaleString()}\nBalance: TSh ${calc.balance.toLocaleString()}`);
        window.loadPrintingQueue();
    }catch(e){ alert('Printing save failed: '+e.message); }
    finally{ if(btn){ btn.disabled=false; btn.innerText=' Save Job'; } }
};

window.reducePrintingPaperStock = async function(ownerUid, sheetsUsed){
    try{
        const qInv=query(collection(db,'products'), where('userId','==',ownerUid));
        const snap=await getDocs(qInv);
        for(const d of snap.docs){ const p=d.data(); const name=String(p.name||p.title||'').toLowerCase(); if(name.includes('karatasi')||name.includes('ream')||name.includes('paper')){ await updateDoc(doc(db,'products',d.id), { stock: increment(-Math.max(1,sheetsUsed)) }); return true; } }
    }catch(e){ console.log('paper stock reduce skipped', e); }
    return false;
};

window.loadPrintingQueue = async function(){
    const box=document.getElementById('printingQueueList'); if(!box || !currentUser) return;
    const ownerUid=currentUserData?.shopOwnerUid || currentUser.uid;
    try{ const qJobs=query(collection(db,'printing_jobs'), where('shopOwnerId','==',ownerUid), orderBy('createdAt','desc'), limit(8)); const snap=await getDocs(qJobs); if(snap.empty){ box.innerHTML='<p style="font-size:12px;color:#64748b;text-align:center;">Hakuna kazi kwenye foleni.</p>'; return;} box.innerHTML=''; snap.forEach(d=>{ const j=d.data(); box.innerHTML += `<div class="prt-queue-item"><div style="display:flex;justify-content:space-between;gap:8px;"><b>${j.jobCode}</b><span class="prt-badge">${j.status}</span></div><div>${skhEscape(j.customerName)} • ${j.jobType}</div><small>${j.pages} pages x ${j.copies} • TSh ${(j.total||0).toLocaleString()}</small></div>`; }); }catch(e){ box.innerHTML='<p style="font-size:12px;color:#e11d48;">Queue imeshindikana: '+e.message+'</p>'; }
};

window.printPrintingReceipt = function(){
    const calc=window.calculatePrintingCost();
    const cust=document.getElementById('prCustName')?.value || 'Customer';
    const html=`PRINTING RECEIPT\nCustomer: ${cust}\nService: ${calc.jobType}\nPages: ${calc.pages}\nCopies: ${calc.copies}\nSheets: ${calc.sheetsUsed}\nTotal: TSh ${calc.total.toLocaleString()}\nBalance: TSh ${calc.balance.toLocaleString()}`;
    alert(html);
};

window.openPrintingModal = function(){ window.closeModals(); const modal=document.getElementById('printingServiceModal'); if(modal){ modal.style.display='flex'; window.renderPrintingModalPro(); } };

