function orchNum(v, fallback=0){ const n=parseFloat(String(v ?? '').replace(/,/g,'')); return Number.isFinite(n)?n:fallback; }
function orchProductMeta(p={}){
    const weightKg = orchNum(p.weightKg ?? p.weight ?? p.productWeight, 1);
    const lengthCm = orchNum(p.lengthCm ?? p.length ?? p.dimL, 20);
    const widthCm = orchNum(p.widthCm ?? p.width ?? p.dimW, 20);
    const heightCm = orchNum(p.heightCm ?? p.height ?? p.dimH, 10);
    return {
        productId:p.id || p.productId || '', productName:p.title || p.name || 'Product', productImages:p.images || (p.image?[p.image]:[]),
        sellerId:p.userId || p.sellerId || '', sellerName:p.ownerName || p.sellerName || p.seller || 'Seller', storeName:p.shopName || p.storeName || p.ownerName || 'Store',
        category:p.category || p.productCategory || 'General', sku:p.sku || p.SKU || ('SKU-'+(p.id||Date.now()).toString().slice(-6)),
        unitPrice:smartCartPrice ? smartCartPrice(p) : orchNum(p.price), discount:orchNum(p.discount,0), tax:orchNum(p.tax,0),
        weightKg, dimensions:{ lengthCm,widthCm,heightCm }, fragile:!!(p.fragile || p.isFragile), hazardous:!!(p.hazardous || p.isHazardous),
        warranty:p.warranty || 'Seller Warranty', returnPolicy:p.returnPolicy || 'SokoHai/Seller return policy', availableStock:p.stock ?? p.quantity ?? p.availableStock ?? '—',
        verificationStatus:p.productVerificationStatus || p.verificationStatus || 'marketplace_listed', preferredShipping:p.preferredShipping || p.shippingRequirements || (p.fragile?'fragile':'standard')
    };
}
function orchPackageSummary(items=smartCartItems()){
    let weight=0, volume=0, fragile=false, hazardous=false, sellers=new Set();
    items.forEach(x=>{ const q=smartCartQty(x); const m=x.cartMeta || orchProductMeta(x); weight += (m.weightKg||1)*q; volume += ((m.dimensions?.lengthCm||20)*(m.dimensions?.widthCm||20)*(m.dimensions?.heightCm||10))*q; fragile = fragile || !!m.fragile; hazardous = hazardous || !!m.hazardous; sellers.add(smartCartSellerId(x)); });
    const sizeClass = weight <= 25 ? 'small' : weight <= 500 ? 'medium' : 'large';
    return { weightKg:Math.round(weight*100)/100, volumeCm3:Math.round(volume), fragile, hazardous, sellersCount:sellers.size, sizeClass };
}
function orchCarrierSuitable(c, pkg, service){
    if(service && c.service !== service) return false;
    if(pkg.weightKg > (c.capacityKg || 0)) return false;
    if(pkg.fragile && !c.insurance && c.service !== 'customer_pickup') return false;
    return true;
}

window.loadSokoHaiCarriers = async function(){
    let carriers=[...window.sokohaiCarrierFallbacks];
    try{
        const qCar=query(collection(db,'transport_profiles'), limit(30));
        const snap=await getDocs(qCar);
        snap.forEach(d=>{ const x=d.data(); carriers.push({ id:d.id, name:x.name||x.companyName||'Transporter', company:x.companyName||x.name||'Transport', service:x.service||'sokohai_logistics', eta:x.eta||'Same/Next Day', vehicleType:x.vehicleType||'Vehicle', vehicle:x.vehicle||x.vehicleType||'Vehicle', capacityKg:orchNum(x.capacityKg||x.capacity,100), capacity:x.capacityLabel||`${x.capacityKg||x.capacity||100} kg`, price:orchNum(x.price||x.basePrice,10000), insurance:!!x.insurance, verified:!!x.verified, rating:x.rating||'—', driverName:x.driverName||'After assignment', driverPhone:x.phone||x.driverPhone||'After assignment', plate:x.plate||x.vehiclePlate||'After assignment', suitableFor:x.suitableFor||['small','medium'], source:'transport_profiles' }); });
    }catch(e){ console.log('transport profiles fallback used', e.message); }
    return carriers;
};

window.selectSmartShippingService = async function(service){
    window.smartCartState.shippingService = service;
    window.smartCartState.selectedCarrier = null;
    await window.renderSmartCartShippingOrchestration(true);
    window.renderSmartCart();
};
window.selectSmartCarrier = function(carrierId){
    const c=(window.smartCartState.availableCarriers||[]).find(x=>x.id===carrierId);
    if(!c) return;
    window.smartCartState.selectedCarrier = c;
    window.smartCartState.shippingMethod = c.service === 'customer_pickup' ? 'pickup' : c.service;
    window.smartCartState.shippingCost = c.price || 0;
    window.renderSmartCart();
};

const _smartCalcOrchOld = window.smartCartCalculate;
window.smartCartCalculate = function(){
    const base = _smartCalcOrchOld ? _smartCalcOrchOld() : { productsTotal:0, sellersCount:0, insurance:0, tax:0, escrowFee:0, discount:0 };
    const selected = window.smartCartState.selectedCarrier;
    const shipping = selected ? orchNum(selected.price,0) : (base.shipping || 0);
    const grandTotal = Math.max(0, base.productsTotal + shipping + (base.insurance||0) + (base.tax||0) + (base.escrowFee||0) - (base.discount||0));
    return { ...base, shipping, grandTotal, package:orchPackageSummary() };
};

window.renderSmartCartShippingOrchestration = async function(skipRender=false){
    const host=document.getElementById('smartShippingOrchestrationHost'); if(!host) return;
    const pkg=orchPackageSummary();
    const service=window.smartCartState.shippingService || 'sokohai_logistics';
    const carriers=await window.loadSokoHaiCarriers();
    const suitable=carriers.filter(c=>orchCarrierSuitable(c,pkg,service)).sort((a,b)=>a.price-b.price);
    window.smartCartState.availableCarriers=suitable;
    if(!window.smartCartState.selectedCarrier && suitable.length) window.smartCartState.selectedCarrier=suitable[0];
    host.innerHTML = `<div class="orch-card"><div class="orch-title"><b> Shipping & Delivery Orchestration</b><span class="scart-badge">Shipment Token Ready</span></div><div class="orch-package-grid"><div class="orch-box"><small>Weight</small><b>${pkg.weightKg} kg</b></div><div class="orch-box"><small>Volume</small><b>${pkg.volumeCm3.toLocaleString()} cm³</b></div><div class="orch-box"><small>Fragile</small><b>${pkg.fragile?'Yes':'No'}</b></div><div class="orch-box"><small>Sellers</small><b>${pkg.sellersCount}</b></div></div><div class="orch-service-tabs">${window.sokohaiShippingServices.map(s=>`<button class="${service===s?'active':''}" onclick="window.selectSmartShippingService('${s}')">${s==='seller_delivery'?'Seller Delivery':s==='sokohai_logistics'?'SokoHai Logistics':s==='third_party_courier'?'3rd Party':'Pickup'}</button>`).join('')}</div><div class="orch-note">Cart imehesabu uzito, vipimo, fragile/hazardous flags na mahitaji ya shipping kabla ya checkout.</div><div style="margin-top:10px;">${suitable.length?suitable.map(c=>`<div class="orch-carrier ${window.smartCartState.selectedCarrier?.id===c.id?'selected':''}"><div><b>${c.name}</b><small>${c.company} • ETA: ${c.eta} • Vehicle: ${c.vehicleType} • Capacity: ${c.capacity}</small><div class="orch-carrier-meta"><span class="orch-chip">TSh ${Number(c.price||0).toLocaleString()}</span><span class="orch-chip">Insurance: ${c.insurance?'Yes':'No'}</span><span class="orch-chip">Verified: ${c.verified?'✓':'Pending'}</span><span class="orch-chip">Rating: ${c.rating}</span><span class="orch-chip">Plate: ${c.plate}</span></div></div><button class="orch-select-btn" onclick="window.selectSmartCarrier('${c.id}')">Select</button></div>`).join(''):'<div class="orch-note">Hakuna carrier anaye-fit package hii. Chagua pickup au punguza mzigo.</div>'}</div></div>`;
};

const _renderSmartCartOrchOld = window.renderSmartCart;
window.renderSmartCart = function(){
    if(_renderSmartCartOrchOld) _renderSmartCartOrchOld();
    const main=document.querySelector('#cartModal .scart-main');
    if(main && !document.getElementById('smartShippingOrchestrationHost')){
        const host=document.createElement('div'); host.id='smartShippingOrchestrationHost';
        const shippingSection=[...main.querySelectorAll('.scart-section')].find(s=>/shipping/i.test(s.textContent||''));
        if(shippingSection) main.insertBefore(host, shippingSection); else main.appendChild(host);
    }
    window.renderSmartCartShippingOrchestration();
};

// Enrich Add to Cart with complete orchestration metadata.
const _orchAddToCartOld = window.addToCart;
window.addToCart = async function(isBuyNow=false){
    if(isBuyNow) return _orchAddToCartOld ? _orchAddToCartOld(true) : null;
    if(!requireAuth()) return;
    if(!currentOpenProduct) return alert('Bidhaa haijapakia vizuri.');
    const qty=parseInt(document.getElementById('pmQty')?.value || '1') || 1;
    const chosenColor=currentOpenProduct?.selectedVariants?.color || currentOpenProduct?.chosenColor || 'N/A';
    const chosenSize=currentOpenProduct?.selectedVariants?.size || currentOpenProduct?.chosenSize || 'N/A';
    let liveProduct={...currentOpenProduct};
    try{ const snap=await getDoc(doc(db,'products', currentOpenProduct.id)); if(snap.exists()) liveProduct={...liveProduct,...snap.data(),id:currentOpenProduct.id}; }catch(e){}
    const cartMeta=orchProductMeta(liveProduct);
    const item={...liveProduct, qty, chosenColor, chosenSize, sellerId:cartMeta.sellerId, sellerName:cartMeta.sellerName, storeName:cartMeta.storeName, cartMeta, escrowEligible:true, addedAt:new Date().toISOString(), orchestrationReady:true};
    myCart=smartCartItems(); myCart.push(item); smartCartSave();
    const badge=document.getElementById('cartBadge'); if(badge){ badge.style.display='flex'; badge.innerText=myCart.length; }
    alert(' Bidhaa imewekwa kwenye SokoCart na taarifa kamili za shipping/escrow.');
};

function orchBuildShipment(core, carrier, calc){
    const shipmentId='SHPID-'+Date.now()+'-'+Math.random().toString(36).slice(2,5).toUpperCase();
    const trackingId='TRK-'+Math.random().toString(36).slice(2,10).toUpperCase();
    return {
        shipmentId, trackingId, shipmentToken:core.shipmentToken, orderId:core.orderId, transactionToken:core.transactionToken, sokopayCoreId:core.sokopayCoreId || '',
        buyerId:core.buyerId, sellerId:core.sellerId, courierId:carrier?.id || 'not_selected', courierName:carrier?.name || 'Not selected', courierCompany:carrier?.company || '',
        driverName:carrier?.driverName || 'After assignment', driverPhone:carrier?.driverPhone || '', vehicleType:carrier?.vehicleType || '', vehiclePlate:carrier?.plate || 'After assignment', capacity:carrier?.capacity || '', insuranceStatus:carrier?.insurance?'insured':'not_insured', verificationBadge:carrier?.verified?'verified':'pending', rating:carrier?.rating || '—',
        pickupLocation:core.items?.[0]?.sellerLocation || core.items?.[0]?.location || 'Seller location', deliveryAddress:document.getElementById('smartShippingAddress')?.value || window.smartCartState.address || '', specialInstructions:document.getElementById('smartOrderNotes')?.value || window.smartCartState.notes || '', package:calc.package, escrowStatus:core.escrowStatus, shippingCost:carrier?.price || calc.shipping, status:'Courier Assigned', timeline:[{title:'Shipment Created',at:new Date().toISOString(),done:true},{title:'Courier Assigned',at:new Date().toISOString(),done:true},{title:'Collected',at:null,done:false},{title:'In Transit',at:null,done:false},{title:'Delivered',at:null,done:false}], createdAt:new Date().toISOString(), updatedAt:new Date().toISOString()
    };
}

// Override core order creation to include selected shipping + logistics assignment + seller inbox.
window.confirmSmartCartOrder = async function(){
    await window.hydrateSmartCartProducts?.();
    const items=smartCartItems(); const calc=window.smartCartCalculate(); if(!items.length) return alert('Cart iko wazi.');
    const carrier=window.smartCartState.selectedCarrier; if(!carrier) return alert('Chagua shipping/courier kabla ya checkout.');
    const transactionToken=smartCartToken(); const orderId='ORD-'+Date.now(); const grouped={}; items.forEach(x=>{ const sid=smartCartSellerId(x); grouped[sid]=grouped[sid]||[]; grouped[sid].push(x); });
    const createdTxIds=[];
    try{
        for(const [sellerId,sellerItems] of Object.entries(grouped)){
            let sellerProfile=null; try{ const s=await getDoc(doc(db,'users',sellerId)); if(s.exists()) sellerProfile=s.data(); }catch(e){}
            let core=buildSokoPayCoreTx({ orderId, transactionToken, sellerId, sellerItems, calc, sellerProfile });
            core.shippingService=carrier.service; core.selectedCarrier=carrier; core.shippingCost=carrier.price||calc.shipping; core.package=calc.package; core.escrowBreakdown={ productCost:core.amount, shippingCost:core.shippingCost, escrowTotal:core.amount+core.shippingCost, escrowFee:calc.escrowFee };
            const coreRef=await addDoc(collection(db,'sokopay_core_transactions'), core); core.sokopayCoreId=coreRef.id; createdTxIds.push(coreRef.id);
            const shipment=orchBuildShipment(core, carrier, calc);
            const shipRef=await addDoc(collection(db,'shipments'), shipment);
            await updateDoc(doc(db,'sokopay_core_transactions',coreRef.id), { shipmentId:shipment.shipmentId, trackingId:shipment.trackingId, shipmentDocId:shipRef.id, shipmentStatus:'Courier Assigned', updatedAt:new Date().toISOString() });
            await addDoc(collection(db,'logistics_assignments'), { ...shipment, shipmentDocId:shipRef.id, assignmentStatus:'new_assignment', logisticsDashboardStatus:'pending_acceptance' });
            await addDoc(collection(db,'seller_order_inbox'), { sellerId, orderId, transactionToken, sokopayCoreId:coreRef.id, shipmentDocId:shipRef.id, buyerDetails:{ buyerId:core.buyerId, buyerName:core.buyerName }, paymentStatus:core.paymentStatus, escrowStatus:core.escrowStatus, selectedShippingCompany:carrier.company, shippingInstructions:shipment.specialInstructions, pickupAddress:shipment.pickupLocation, deliveryAddress:shipment.deliveryAddress, items:sellerItems, createdAt:new Date().toISOString(), status:'new_order' });
            await addDoc(collection(db,'orders'), { ...core, sokopayCoreId:coreRef.id, shipmentDocId:shipRef.id, status:'payment_pending', itemTitle:`Smart Cart Order (${sellerItems.length} items)`, shipping:{ method:carrier.service, carrier, shipment }, orderNotes:shipment.specialInstructions, paymentMethod:window.smartCartState.paymentMethod });
            await addDoc(collection(db,'notifications'), { userId:core.outsideSeller?'platform_admin':sellerId, title:' New SokoCart Order', body:`${orderId} • ${transactionToken} • ${carrier.name} • TSh ${(core.amount+core.shippingCost).toLocaleString()}`, createdAt:new Date().toISOString(), read:false, sellerPortalToken:core.sellerPortalToken });
        }
        await addDoc(collection(db,'smart_cart_checkouts'), { orderId, transactionToken, buyerId:currentUser.uid, sokopayCoreIds:createdTxIds, items, totals:calc, selectedCarrier:carrier, package:calc.package, paymentMethod:window.smartCartState.paymentMethod, createdAt:new Date().toISOString() });
        sessionStorage.setItem('pending_sokopay_core_ids', JSON.stringify(createdTxIds)); sessionStorage.setItem('smart_cart_checkout_token', transactionToken);
        alert(` Package kamili imetumwa SokoPay Core\nOrder: ${orderId}\nToken: ${transactionToken}\nShipping: ${carrier.name}\nEscrow Total: TSh ${calc.grandTotal.toLocaleString()}`);
        activeCheckoutAmount=calc.grandTotal; document.getElementById('checkoutAmount').value=`TSh ${calc.grandTotal.toLocaleString()}`; myCart=[]; smartCartSave(); closeModals(); document.getElementById('checkoutModal').style.display='flex';
    }catch(e){ alert('Order orchestration failed: '+e.message); }
};

