window.createOutsideSellerTransaction = async function(){
    const product=document.getElementById('outProduct')?.value?.trim(); const amount=orchNum(document.getElementById('outAmount')?.value,0); const phone=document.getElementById('outSellerPhone')?.value?.trim();
    if(!product||amount<=0) return alert('Jaza product na amount.');
    const orderId='OUT-'+Date.now(); const transactionToken='SPT-'+Math.random().toString(36).slice(2,10).toUpperCase(); const sellerPortalToken='SEL-'+Math.random().toString(36).slice(2,10).toUpperCase();
    const tx={ orderId, transactionToken, paymentToken:'PAY-'+orderId, shipmentToken:'SHP-'+orderId, escrowToken:'ESC-'+orderId, verificationToken:'VER-'+orderId, buyerId:currentUser?.uid||'external_buyer', buyerName:currentUser?.displayName||'Buyer', sellerId:'outside_seller_'+sellerPortalToken, sellerName:'Outside Seller', outsideSeller:true, sellerPortalToken, sellerPortalLink:`sokohai://seller-portal/${sellerPortalToken}`, sellerDetails:{ supportContact:phone, businessName:'Outside Seller' }, items:[{ title:product, price:amount, qty:1, outsideSeller:true, sellerPhone:phone }], amount, totals:{ grandTotal:amount }, paymentStatus:'Payment Pending', escrowStatus:'Waiting Payment', shipmentStatus:'Waiting Shipment', contractStatus:'Contract Active', orderStatus:'Pending', tokenStatus:'Tokens Ready', timeline:spTimelineBase().map((x,i)=>({title:x[0],description:x[1],at:i===0?new Date().toISOString():null,done:i===0})), createdAt:new Date().toISOString(), source:'outside_seller_portal' };
    const ref=await addDoc(collection(db,'sokopay_core_transactions'), tx);
    document.getElementById('outsideSellerResult').innerHTML=`<div class="spbuyer-card"><b> Token Generated</b><p>Transaction Token: <b>${transactionToken}</b><br>Seller Portal Token: <b>${sellerPortalToken}</b></p><button class="spbuyer-btn primary" onclick="window.skhCopyText('${transactionToken}')">Copy Token</button><button class="spbuyer-btn light" onclick="window.openSokoPayOrderDetail('${ref.id}')">Open Buyer View</button></div>`;
};

