// Disable the old intrusive global back button behavior. Back button appears only when explicitly inside overlays.
window.skhRefreshBackButton = function(){
    const btn=document.getElementById('skhGlobalBackBtn');
    const overlays = typeof window.skhVisibleOverlays==='function' ? window.skhVisibleOverlays() : [];
    document.body.classList.toggle('skh-overlay-active', overlays.length>0);
    if(btn){
        btn.classList.toggle('skh-allowed', overlays.length>0);
        btn.classList.toggle('show', overlays.length>0);
    }
};

window.skhAddInlineBackButtons = function(){
    document.querySelectorAll('.overlay-menu').forEach(modal=>{
                const card=Array.from(modal.children).find(ch=>ch.nodeType===1);
        if(!card) return;
        const existing=card.querySelector('.skh-inline-back-btn');
        // Only add to important large overlays; not to every tiny generated panel.
        const allowedIds=['cartModal','checkoutModal','logisticsMarketplaceModal','sokopayBuyerOrdersModal','sellerOrderInboxModal','logisticsOpsModal','printingServiceModal','sidebarMenuModal','sokohaiAccountSettingModal','outsideSellerPortalModal','unifiedTokenCenterModal','trackingTokenLookupModal'];
        if(!allowedIds.includes(modal.id)) return;
        if(existing) return;
        const b=document.createElement('button'); b.className='skh-inline-back-btn'; b.type='button'; b.innerHTML='← Rudi Nyuma'; b.onclick=window.skhGoBack;
        try{ card.insertBefore(b, card.firstElementChild); }catch(e){}
    });
};

// Remove friendly helper if it appears near search/top.
window.skhFriendlyModuleHeader = function(){ const el=document.getElementById('skhFriendlySectionCard'); if(el) el.remove(); };
setInterval(()=>{ document.getElementById('skhFriendlySectionCard')?.remove(); }, 1000);

// Ensure bottom nav never covers typing fields.
document.addEventListener('focusin', e=>{
    if(e.target && /INPUT|TEXTAREA|SELECT/.test(e.target.tagName)){
        document.body.classList.add('skh-keyboard-open');
        setTimeout(()=>{ try{ e.target.scrollIntoView({block:'center',behavior:'smooth'}); }catch(_){} },180);
    }
}, true);
document.addEventListener('focusout', ()=> setTimeout(()=>document.body.classList.remove('skh-keyboard-open'),250), true);

// Final cleanup command
window.scanAndFixSokoHaiUI = function(){
    document.getElementById('skhFriendlySectionCard')?.remove();
    window.skhRefreshBackButton?.();
    window.skhAddInlineBackButtons?.();
    // Alert removed: UI scan/fix now runs silently.
};
setTimeout(()=>window.scanAndFixSokoHaiUI?.(),1200);

